    #[test]
    fn the_head_kept_the_developer_tools_and_gave_the_other_three_to_the_rail() {
        let metrics = seat_metrics(1_000);
        let mut seats = Seats::lone_terminal();
        seats.add_preview(&metrics).expect("the preview seat lands");
        let layout = solved(&seats, viewport_of(1600, 900, 1_000), &metrics);
        let seat = seats.preview().expect("the preview seat");
        let rect = full_pane_rect(&layout, seat).expect("a full pane");
        let head = pane_head_geometry(rect, SeatKind::Preview, 1.0);
        let page = PreviewHeadTools {
            web: true,
            name_width: 60.0,
            ..PreviewHeadTools::default()
        };
        let geometry = preview_head_geometry(&head, 1.0, page);
        let devtools = geometry
            .devtools
            .expect("a page's head keeps its way in to the page's own source");
        let popout = geometry.popout.expect("a pop-out box");
        let lock = geometry.lock.expect("a lock box");
        assert!(
            devtools[2] <= popout[0] && popout[2] <= lock[0],
            "what a page contributes still stands ahead of the three every pane \
             has"
        );
        assert_eq!(
            [devtools[2] - devtools[0], devtools[3] - devtools[1]],
            [popout[2] - popout[0], popout[3] - popout[1]],
            "one family, one box"
        );
        assert!(
            geometry.name[2] <= devtools[0],
            "and the name is cut short of it, not drawn under it"
        );
        // The per-type slot is still the per-type slot, and the developer tools
        // are still its outermost member — the mock-up's own DOM order with four
        // fewer controls in it.
        let dressed = preview_head_geometry(
            &head,
            1.0,
            PreviewHeadTools {
                save: true,
                flip: true,
                ..page
            },
        );
        let (save, flip) = (
            dressed.save.expect("a save box"),
            dressed.flip.expect("a flip box"),
        );
        assert!(
            save[2] <= flip[0] && flip[2] <= dressed.devtools.expect("a devtools box")[0],
            "`Save`, the flip and then the developer tools"
        );
        // ③ A page reserves exactly one box more than a plain head, and it is
        // that one: the boxes of the controls that were always there do not move
        // when a page arrives.
        let plain = preview_head_geometry(&head, 1.0, PreviewHeadTools { web: false, ..page });
        assert_eq!(plain.devtools, None, "no page, no developer tools");
        assert_eq!(
            (plain.popout, plain.lock),
            (geometry.popout, geometry.lock),
            "and the run's other boxes are where they always were"
        );
    }

    /// RAIL (user ruling 2026-08-24) — **the address row's controls answer for
    /// their own rectangles, and the four that moved kept their targets.**
    ///
    /// The second half of the re-judgement above. `PreviewBack`, `PreviewForward`,
    /// `PreviewReload` and `PreviewBrowser` are the very targets the head used to
    /// answer with, because a press that means one thing gets one target however
    /// many rows the button has stood in — the dispatch did not change, only the
    /// geometry that produces it.
    ///
    /// MUTATIONS:
    /// ① mint new targets for the moved buttons — the dispatch in `main.rs` no
    ///    longer routes them and every one of these goes red;
    /// ② let the band answer before its controls — every assertion here becomes
    ///    `PreviewRail`, which is the picture of a row you cannot press anything
    ///    on;
    /// ③ drop the band's own catch-all — the last assertion goes red, and a
    ///    press between two buttons drags the pane by a row that is not its head.
    #[test]
    fn the_address_row_answers_for_every_control_the_head_handed_it() {
        let metrics = seat_metrics(1_000);
        let mut seats = Seats::lone_terminal();
        seats.add_preview(&metrics).expect("the preview seat lands");
        let layout = solved(&seats, viewport_of(1600, 900, 1_000), &metrics);
        let seat = seats.preview().expect("the preview seat");
        let rect = full_pane_rect(&layout, seat).expect("a full pane");
        let measure = PreviewRailMeasure {
            kind: PreviewRailKind::Address,
            address_width: 180.0,
            ..PreviewRailMeasure::default()
        };
        let geometry = preview_rail_geometry(rect, 1.0, &measure);
        let rails = [(seat, measure.clone())];
        let centre = |box_: [f32; 4]| {
            (
                f64::from((box_[0] + box_[2]) / 2.0),
                f64::from((box_[1] + box_[3]) / 2.0),
            )
        };
        for (box_, expected) in [
            (geometry.back, ChromeTarget::PreviewBack(seat)),
            (geometry.forward, ChromeTarget::PreviewForward(seat)),
            (geometry.reload, ChromeTarget::PreviewReload(seat)),
            (geometry.copy, ChromeTarget::PreviewAddressCopy(seat)),
            (geometry.external, ChromeTarget::PreviewBrowser(seat)),
            (geometry.address, ChromeTarget::PreviewAddress(seat)),
        ] {
            let (x, y) = centre(box_.expect("a row this wide seats every control"));
            assert_eq!(
                hit_preview_rail(&layout, 1.0, &rails, x, y),
                Some(expected),
                "{expected:?} answers for its own rectangle"
            );
        }
        // The arrangement the ruling asked for: navigation on the left, the two
        // address verbs on the right, the address between them — and the arrow
        // outermost of the pair, because it is the one that leaves the window.
        let (back, forward, reload) = (
            geometry.back.expect("a back box"),
            geometry.forward.expect("a forward box"),
            geometry.reload.expect("a reload box"),
        );
        let (copy, external) = (
            geometry.copy.expect("a copy box"),
            geometry.external.expect("an external box"),
        );
        let field = geometry.address.expect("an address field");
        assert!(back[2] <= forward[0] && forward[2] <= reload[0]);
        assert!(reload[2] <= field[0] && field[2] <= copy[0]);
        assert!(copy[2] <= external[0]);
        assert!(
            external[2] <= geometry.band[2],
            "and nothing hangs off the row's own edge"
        );
        // **地址居中** — centred on the band, not on the gap the two runs left.
        let band_middle = (geometry.band[0] + geometry.band[2]) / 2.0;
        let field_middle = (field[0] + field[2]) / 2.0;
        assert!(
            (field_middle - band_middle).abs() <= 1.0,
            "the address is centred in the row, not in the leftovers"
        );
        // ③ The band swallows what its controls left over.
        let gap = (reload[2] + field[0]) / 2.0;
        assert_eq!(
            hit_preview_rail(
                &layout,
                1.0,
                &rails,
                f64::from(gap),
                f64::from((geometry.band[1] + geometry.band[3]) / 2.0),
            ),
            Some(ChromeTarget::PreviewRail(seat)),
            "a press between two controls is still a press on the row"
        );
    }

    /// RAIL (user ruling 2026-08-24) — **the breadcrumb row: every segment is a
    /// button, the last one is this file, and a path too long folds in the
    /// middle.**
    ///
    /// The three sentences of the ruling's ② and ③ that a reader can measure.
    /// What the fold keeps is the part a reader cannot spare — the root says
    /// which tree this is and the tail says which file — so the segments between
    /// them are what leave, nearest the root first.
    ///
    /// MUTATIONS:
    /// ① fold from the tail rather than from the middle — the file's own name
    ///    disappears from the row that is about it and the tail assertion goes
    ///    red;
    /// ② index the press by the drawn run rather than by the whole path — every
    ///    segment after the `…` points at the wrong folder, which the depth
    ///    assertion catches;
    /// PIN (§7.7 ⑪ 欠账, 2026-08-25) — **splitting the band off the contents
    /// changed no pixel of the row a pane wears.**
    ///
    /// [`preview_rail_geometry_in`] exists so a torn-off window can hand in the
    /// band its own chassis reserved; the moment it stopped being the same
    /// derivation as the pane's, the two hosts would be two rows. So the pane's
    /// entry is asserted to *be* the general one applied to the pane's own band,
    /// on both fillings and at a width where the fold has fired.
    ///
    /// Mutation: derive the band inside `preview_rail_geometry_in` from anything
    /// but its argument and this goes red on the first field.
    #[test]
    fn a_panes_rail_is_the_general_row_laid_into_the_panes_own_band() {
        const SCALE: f32 = 1.5;
        let rect = [0.0, 0.0, 620.0, 480.0];
        for measure in [
            PreviewRailMeasure {
                kind: PreviewRailKind::Address,
                address_width: 210.0,
                ..PreviewRailMeasure::default()
            },
            PreviewRailMeasure {
                kind: PreviewRailKind::Crumbs,
                segments: vec![24.0, 70.0, 64.0, 58.0, 96.0],
                flip: true,
                open_width: 34.0,
                notice_width: 62.0,
                ..PreviewRailMeasure::default()
            },
        ] {
            let band = preview_rail_band(rect, SCALE);
            assert_eq!(
                preview_rail_geometry(rect, SCALE, &measure),
                preview_rail_geometry_in(band, SCALE, &measure),
                "one derivation, whichever host cut the band"
            );
        }
    }

    /// PIN — **what the pointer is on, and what each host calls it.**
    ///
    /// [`preview_rail_part`] is the ladder both a pane and a window climb, and
    /// the two name-maps around it are what let a pane go on speaking
    /// [`ChromeTarget`]: [`preview_rail_target`] going out to the hit test,
    /// [`preview_rail_hover`] coming back in to the paint. A round trip that
    /// lost a control is a button that answers a press and never lights under
    /// the pointer — which is exactly what the paint's own comparison used to
    /// guarantee by construction and now has to be pinned.
    ///
    /// Mutation ①: drop an arm of `preview_rail_hover` and that control stops
    /// lighting — red here. Mutation ②: answer another seat's target and the
    /// last block goes red, which is one pane's button lit by a pointer standing
    /// on another's.
    #[test]
    fn every_rail_control_survives_the_trip_out_to_a_seat_and_back() {
        let seat = SeatId(3);
        let other = SeatId(4);
        for kind in [PreviewRailKind::Address, PreviewRailKind::Crumbs] {
            for part in [
                PreviewRailPart::Back,
                PreviewRailPart::Forward,
                PreviewRailPart::Reload,
                PreviewRailPart::Browser,
                PreviewRailPart::Flip,
                PreviewRailPart::OpenWith,
                PreviewRailPart::Copy,
                PreviewRailPart::Address,
                PreviewRailPart::Fold,
                PreviewRailPart::Crumb(2),
                PreviewRailPart::Band,
            ] {
                let target = preview_rail_target(part, seat, kind);
                assert_eq!(
                    preview_rail_hover(Some(target), seat),
                    Some(part),
                    "{part:?} on a {kind:?} row answers the pointer and lights under it"
                );
                assert_eq!(
                    preview_rail_hover(Some(target), other),
                    None,
                    "and it is this seat's control and not the pane next door's"
                );
            }
        }
        // The `⧉` is the one glyph with a sentence for each row, so it is the
        // one place the trip out is not injective on the part alone — said out
        // loud, because it is the shape a lazy round trip would get wrong.
        assert_ne!(
            preview_rail_target(PreviewRailPart::Copy, seat, PreviewRailKind::Address),
            preview_rail_target(PreviewRailPart::Copy, seat, PreviewRailKind::Crumbs),
            "one glyph, two verbs, and the row's kind is what tells them apart"
        );
    }

    /// ③ let the crumbs run under the verbs — the last assertion goes red, and
    ///    `Open ⌄` is drawn over a folder name.
    #[test]
    fn a_breadcrumb_folds_its_middle_and_every_segment_answers_for_its_own_depth() {
        let metrics = seat_metrics(1_000);
        let mut seats = Seats::lone_terminal();
        seats.add_preview(&metrics).expect("the preview seat lands");
        let layout = solved(&seats, viewport_of(1600, 900, 1_000), &metrics);
        let seat = seats.preview().expect("the preview seat");
        let rect = full_pane_rect(&layout, seat).expect("a full pane");
        let measure = PreviewRailMeasure {
            kind: PreviewRailKind::Crumbs,
            segments: vec![26.0, 70.0, 90.0, 48.0, 120.0],
            flip: true,
            open_width: 32.0,
            ..PreviewRailMeasure::default()
        };
        let geometry = preview_rail_geometry(rect, 1.0, &measure);
        assert_eq!(geometry.fold, None, "a path that fits is drawn entire");
        assert_eq!(geometry.crumbs.len(), 5);
        assert!(
            geometry.crumbs.last().expect("a tail").tail,
            "the last segment is this file"
        );
        assert!(
            geometry.crumbs[..4].iter().all(|crumb| !crumb.tail),
            "and nothing above it is"
        );
        let rails = [(seat, measure.clone())];
        for crumb in &geometry.crumbs {
            assert_eq!(
                hit_preview_rail(
                    &layout,
                    1.0,
                    &rails,
                    f64::from((crumb.rect[0] + crumb.rect[2]) / 2.0),
                    f64::from((crumb.rect[1] + crumb.rect[3]) / 2.0),
                ),
                Some(ChromeTarget::PreviewCrumb {
                    seat,
                    depth: crumb.depth
                }),
                "every segment answers for its own depth"
            );
        }
        // ③ The verbs own the right end, and the crumbs stop before them.
        let flip = geometry.flip.expect("a flip box");
        let copy = geometry.copy.expect("a copy box");
        let open = geometry.open.expect("an Open pill");
        assert!(flip[2] <= copy[0] && copy[2] <= open[0]);
        assert!(
            geometry.crumbs.last().expect("a tail").rect[2] <= flip[0],
            "the path yields to the verbs rather than running under them"
        );

        // ① A path with no room folds its middle: the root, the `…`, and as much
        // of the tail end as fits.
        let narrow = PreviewRailMeasure {
            segments: vec![26.0, 300.0, 300.0, 300.0, 120.0],
            ..measure
        };
        let folded = preview_rail_geometry(rect, 1.0, &narrow);
        let chip = folded.fold.expect("a path this long folds");
        assert!(
            !folded.folded.is_empty(),
            "and the `…` stands for the segments it hid"
        );
        assert!(
            folded.folded.iter().all(|depth| *depth > 0 && *depth < 4),
            "what folds is the middle: never the root, never the file"
        );
        assert!(
            folded.crumbs.last().expect("a tail").tail,
            "the file survives the fold"
        );
        // **Where the chip stands is the whole of what it means** (found on a
        // real window, 2026-08-24): the root it did not swallow is drawn to its
        // *left*, and the segments it stands for are the ones between them. A
        // chip laid down before the run reads `… › D: › docs › name.md`, which
        // says there is a folder above the drive.
        let root = folded.crumbs.first().expect("the root survived this fold");
        assert_eq!(root.depth, 0, "the root is the first thing drawn");
        assert!(
            root.rect[2] <= chip[0],
            "and the `…` stands after it, where the folders it replaced stood"
        );
        assert!(
            chip[2] <= folded.crumbs.last().expect("a tail").rect[0],
            "and before the file it did not swallow"
        );
        assert_eq!(
            hit_preview_rail(
                &layout,
                1.0,
                &[(seat, narrow)],
                f64::from((chip[0] + chip[2]) / 2.0),
                f64::from((chip[1] + chip[3]) / 2.0),
            ),
            Some(ChromeTarget::PreviewCrumbFold(seat)),
            "the `…` is a button onto what is behind it"
        );
    }

    /// PIN (user report on a real window, 2026-08-19) — **an inline name
    /// editor's caret is a hairline as tall as its TEXT LINE, on every surface
    /// that has one.**
    ///
    /// The preview head drew it to the name's own box, and that box is a pane
    /// header's content band: a full-height rule stood beside a 12.5px file
    /// name, which reads as a divider rather than as an insertion point. The tab
    /// strip had it right all along — the tab's 15px mark slot — and the fix is
    /// not to copy that number here but to have one function answer for all
    /// three surfaces.
    ///
    /// This asserts the property rather than the number: whatever box the
    /// editor is drawn in, the caret and the selection are
    /// [`INLINE_RENAME_LINE_LOGICAL_PX`] tall and centred in it.
    ///
    /// Red gate: give the preview head back `geometry.name`'s own height and the
    /// second case goes red by the difference between a pane header and a line
    /// of text.
    #[test]
    fn an_inline_editors_caret_is_as_tall_as_its_line_and_never_as_tall_as_its_box() {
        let edit = TabEdit {
            text: "notes.md".to_owned(),
            placeholder: String::new(),
            caret_px: 20.0,
            selection_px: 34.0,
            caret_lit: true,
        };
        for scale in [1.0_f32, 1.5, 2.0] {
            let line = (INLINE_RENAME_LINE_LOGICAL_PX * scale).round();
            // A tab body and a preview head are very different heights; the name
            // inside them is not, which is the whole claim.
            for box_ in [
                [100.0, 0.0, 300.0, 32.0 * scale],
                [100.0, 0.0, 300.0, 44.0 * scale],
                [100.0, 12.0 * scale, 300.0, 12.0 * scale + 19.0 * scale],
            ] {
                let marks = inline_rename_marks(box_, &edit, scale);
                let caret = marks.caret.expect("a lit caret inside the box");
                let band = marks.selection.expect("a selection with width");
                assert!(
                    (caret[3] - caret[1] - line).abs() <= 1.0,
                    "scale {scale}, box {box_:?}: caret is {} tall, wanted {line}",
                    caret[3] - caret[1]
                );
                assert_eq!(
                    [caret[1], caret[3]],
                    [band[1], band[3]],
                    "the caret and the band stand on one line"
                );
                let middle = (box_[1] + box_[3]) / 2.0;
                assert!(
                    ((caret[1] + caret[3]) / 2.0 - middle).abs() <= 1.0,
                    "and that line is centred in the box"
                );
                assert!(
                    caret[3] - caret[1] < box_[3] - box_[1],
                    "a caret is never as tall as the box it stands in"
                );
                let width = (TAB_RENAME_CARET_LOGICAL_PX * scale).round().max(1.0);
                assert_eq!(caret[2] - caret[0], width, "and it is a hairline");
            }
        }
        // **A caret at or past the box's own right edge is CLAMPED, never
        // dropped** (user report 2026-08-19). It used to be dropped, and the
        // surface that paid was the preview head: its name box is the draft's
        // own measured width, so a caret at the end of the draft lands exactly
        // on the right edge and drew no insertion point at all. `End`, a
        // whole-draft selection and typing to the end all put it there, which is
        // why this stays after the seed that used to put it there on the opening
        // frame was fixed. A field's last legal caret position is against its
        // right edge.
        //
        // Red gate: put `left + width <= box_[2]` back in front of the caret and
        // both of these go `None`.
        for caret_px in [200.0_f32, 4_000.0] {
            let outside = TabEdit {
                caret_px,
                ..edit.clone()
            };
            let caret = inline_rename_marks([100.0, 0.0, 300.0, 32.0], &outside, 1.0)
                .caret
                .expect("a caret at the far edge is still a caret");
            assert_eq!(
                [caret[0], caret[2]],
                [299.0, 300.0],
                "and it stands on the last hairline the box holds"
            );
        }
        // **AND A CARET THAT IS NOT AT THE END OF THE DRAFT STANDS ON THE
        // SELECTION'S EDGE, NOT ON THE BOX'S** (user report 2026-08-20,
        // screenshot `[Cargo].toml|`).
        //
        // This is the drawn half of `TabRename::seed`'s invariant, and it is the
        // reason the clamp above is not a licence to put every caret at the far
        // edge: a file rename opens with the stem selected, so `caret_px` equals
        // `selection_px`, and what the reader must see is one hairline standing
        // where the wash stops — inside a box the head sized to the whole name.
        // The box here is the draft's own width the way the preview head sizes
        // it, so "on the band's edge" and "on the box's edge" are genuinely
        // different pixels and the assertion can tell them apart.
        let box_ = [100.0_f32, 0.0, 100.0 + 62.0, 32.0];
        let opened = TabEdit {
            caret_px: 34.0,
            selection_px: 34.0,
            ..edit.clone()
        };
        let marks = inline_rename_marks(box_, &opened, 1.0);
        let caret = marks
            .caret
            .expect("the opening frame draws an insertion point");
        let band = marks.selection.expect("under a stem that is selected");
        assert_eq!(
            caret[0], band[2],
            "the hairline stands where the wash stops"
        );
        assert!(
            caret[2] < box_[2],
            "and that is short of the box's own right edge, which is where the \
             end of the draft would have put it"
        );
        let dark = TabEdit {
            caret_lit: false,
            ..edit
        };
        assert_eq!(
            inline_rename_marks([100.0, 0.0, 300.0, 32.0], &dark, 1.0).caret,
            None,
            "and neither is one in the dark half of its blink"
        );
    }

    /// PIN (user ruling 2026-08-19) — **there is ONE inline name editor, and
    /// every surface that has one goes through it.**
    ///
    /// The report was about consistency rather than about a pixel: "改名的方式
    /// 不应该做得和 tab 的类似吗,不然 UI/UX 就不连贯不一致了". Two editors
    /// that look alike are two editors, and the way for them to diverge is for
    /// one of them to be touched.
    ///
    /// Written against the SOURCE rather than against a rendered frame, because
    /// what is being pinned is that nobody minted a second caret — a claim about
    /// the code, which a picture of one surface cannot make. The state machine
    /// is shared one crate over (`TabRename`, `rename_key`, `RenameVerdict`,
    /// `finish_rename`, `KeyboardOwner::Rename`); this is the drawing half.
    ///
    /// Red gate: hand-roll the caret rectangle at any of the three sites and the
    /// second assertion finds the arithmetic that was supposed to have one home.
    #[test]
    fn one_function_draws_every_inline_name_editors_caret() {
        // Split at the test module rather than at the first `#[cfg(test)]`:
        // this file carries test-only helpers well above it, and a split there
        // would read a tenth of the file and call it the whole.
        let source = include_str!("seats.rs")
            .split(
                "
mod tests {",
            )
            .next()
            .expect("a split always yields a first piece");
        assert_eq!(
            source.matches("inline_rename_marks(").count(),
            6,
            "one definition and five callers — the strip, the rail, the preview \
             head, the address row that took the head's field on 2026-08-24, \
             and the breadcrumb's last segment since B5"
        );
        // The hairline's width and the line it stands on are named in exactly
        // one place each, and that place is the shared function.
        assert_eq!(
            source.matches("TAB_RENAME_CARET_LOGICAL_PX").count(),
            2,
            "the caret's width is declared once and read once"
        );
        assert_eq!(
            source.matches("INLINE_RENAME_LINE_LOGICAL_PX").count(),
            3,
            "and so is the line it stands in — its declaration, the doc line              that names it from `inline_rename_marks`, and the one read"
        );
    }

    /// Every `ChromeMark::Fill` a run of chrome drew, in draw order — the three
    /// rectangles an open inline editor puts down, and nothing else in this
    /// window uses that mark.
    fn fills(sprites: &[ChromeSprite]) -> Vec<ChromeSprite> {
        sprites
            .iter()
            .filter(|sprite| sprite.mark == ChromeMark::Fill)
            .copied()
            .collect()
    }

    /// PIN (user report on a real window, 2026-08-19, two screenshots) — **an
    /// open inline name editor is DRAWN AS A FIELD, and it is drawn through the
    /// path the window actually runs.**
    ///
    /// Two things were reported and they have one root: for as long as the
    /// editor was open the only mark it ever made was a selection band, so
    /// - a tab with no name of its own opened its editor with nothing selected
    ///   and therefore with no mark at all, and every editor lost its last mark
    ///   at the first keystroke (the selection collapses), and
    /// - the preview head, whose name box is the draft's own measured width and
    ///   whose caret at that time opened at the END of the file name (a separate
    ///   bug in the editor's seed, fixed 2026-08-20), had its caret refused by a
    ///   bounds test for being one hairline past the box's right edge — so that
    ///   surface drew no insertion point at all, ever. `End` still walks there,
    ///   so the clamp that replaced the bounds test is still what is tested.
    ///
    /// # Why the pin that existed did not hold
    ///
    /// [`one_function_draws_every_inline_name_editors_caret`] is written against
    /// this file's own source text: it counts how many times
    /// `inline_rename_marks(` appears and calls that one editor. That claim is
    /// worth making and it was true the whole time — and it is *lexical*. It
    /// cannot see a colour, an opacity, a bounds test, or whether the sprite it
    /// counted ever reached a frame, which is the entire category the report
    /// falls into. So this one goes the other way round: it builds real chrome
    /// through `strip_chrome_of` and `preview_chrome` — the same two functions
    /// one frame of the runtime goes through — and reads the sprites that come
    /// out.
    ///
    /// Red gate: drop the field from `inline_rename_marks` and the first
    /// assertion of each surface goes red; put `left + width <= box_[2]` back in
    /// front of the caret and the preview head's caret goes missing; give the
    /// field and the selection one colour again and the ink assertion goes red.
    #[test]
    fn an_open_inline_name_editor_is_drawn_as_a_field_on_every_surface() {
        let palette = chrome_palette();
        // ── the tab strip ──────────────────────────────────────────────────
        let editing = |edit: Option<TabEdit>| {
            let tabs = [TabContent {
                mark_kind: ChromeMark::ProfilePowerShell,
                title: "left".to_owned(),
                pane_count: 1,
                edit,
                ..TabContent::default()
            }];
            let (_, _, sprites) = strip_chrome_of(1.0, &tabs, 0, 0.0, None, false);
            fills(&sprites)
        };
        assert!(
            editing(None).is_empty(),
            "a tab that is not being renamed draws no field, no band and no caret"
        );
        // The state the report is about: an auto-named tab, whose editor opens
        // holding nothing, so there is no selection to stand in for a field.
        let typing = editing(Some(TabEdit {
            text: String::new(),
            placeholder: "PowerShell 7".to_owned(),
            caret_px: 0.0,
            selection_px: 0.0,
            caret_lit: true,
        }));
        assert_eq!(
            typing.len(),
            2,
            "a field and a caret — the two marks that are true of every open              editor, selection or no selection"
        );
        let (field, caret) = (typing[0], typing[1]);
        assert!(
            field.rect[0] <= caret.rect[0] && caret.rect[2] <= field.rect[2],
            "the caret stands inside the field: field {:?}, caret {:?}",
            field.rect,
            caret.rect
        );
        assert_ne!(
            field.color, caret.color,
            "and it is not the same ink as the ground it stands on"
        );
        // With a selection, the field is still the first mark down and the band
        // is a different ink from it — otherwise the selection is invisible,
        // which is what having them share a colour used to mean.
        let selected = editing(Some(TabEdit {
            text: "left".to_owned(),
            placeholder: String::new(),
            caret_px: 22.0,
            selection_px: 22.0,
            caret_lit: true,
        }));
        assert_eq!(selected.len(), 3, "field, selection, caret");
        let (field, band) = (selected[0], selected[1]);
        assert!(
            field.rect[0] <= band.rect[0]
                && band.rect[2] <= field.rect[2]
                && field.rect[2] - field.rect[0] > band.rect[2] - band.rect[0],
            "the band is a run inside the field, not the field itself"
        );
        assert_ne!(
            (field.color, field.opacity),
            (band.color, band.opacity),
            "and a selection you cannot tell from its own ground is not a              selection"
        );
        assert_eq!(
            (band.color, band.opacity),
            (palette.accent, INLINE_RENAME_SELECTION_ALPHA),
            "the dialog's own field selection, so this window has one of them"
        );

        // ── the preview head ───────────────────────────────────────────────
        // `caret_px` at the box's own far edge is not an edge case here: the
        // head sizes its name box to the draft, and `TabRename::open_file` puts
        // the caret at the end of the name. 4000 is the same claim made loudly.
        let head = |edit: Option<PreviewNameEdit<'_>>| {
            let (_, _, sprites) = preview_chrome(
                PreviewHeadContent {
                    tools: PreviewHeadTools {
                        save: true,
                        flip: true,
                        web: false,
                        switcher: true,
                        locked: false,
                        name_width: 120.0,
                        count_width: 8.0,
                    },
                    name: "CONVENTIONS.md",
                    dirty: false,
                    count: "2",
                    others_dirty: false,
                    flip_to_source: true,
                    menu_open: false,
                    edit,
                },
                ChromePointer::default(),
            );
            fills(&sprites)
        };
        assert!(
            head(None).is_empty(),
            "a head that is not being renamed draws no field, no band and no caret"
        );
        let editing_head = head(Some(PreviewNameEdit {
            text: "CONVENTIONS.md",
            caret_px: 4_000.0,
            selection_px: 80.0,
            caret_lit: true,
            refused: false,
        }));
        assert_eq!(
            editing_head.len(),
            3,
            "field, selection and — the whole of the second report — a caret"
        );
        let (field, band, caret) = (editing_head[0], editing_head[1], editing_head[2]);
        assert_eq!(
            caret.rect[2], field.rect[2],
            "a caret at the end of the name stands on the field's last hairline              rather than being refused for reaching it"
        );
        assert!(
            band.rect[2] <= field.rect[2] && field.rect[0] <= band.rect[0],
            "and the band is inside the field here too"
        );
        assert_ne!(field.color, caret.color);
        assert_ne!((field.color, field.opacity), (band.color, band.opacity));
    }

    /// Opening the preview narrows the terminal and closing it hands the pixels
    /// back — bit for bit, because closing promotes the sibling and rebalances
    /// the run it was left in, which for a run of one is the whole slot.
    #[test]
    fn opening_and_closing_the_preview_restores_the_terminals_own_rectangle() {
        let mut seats = Seats::lone_terminal();
        let metrics = seat_metrics(1_000);
        let viewport = viewport_of(1600, 900, 1_000);
        let before = solved(&seats, viewport, &metrics)
            .get(seats.identity())
            .unwrap()
            .device_rect
            .unwrap();

        seats.add_preview(&metrics).expect("the preview must open");
        assert!(seats.preview().is_some());
        let narrowed = solved(&seats, viewport, &metrics)
            .get(seats.identity())
            .unwrap()
            .device_rect
            .unwrap();
        assert!(
            narrowed.width() < before.width(),
            "the fixed right seat narrows the root run — that is its stated cost"
        );
        assert_eq!(
            narrowed.height(),
            before.height(),
            "a row split takes no height"
        );

        let preview = seats.preview().expect("the preview seat is open");
        assert!(
            seats.close_seat(&metrics, preview),
            "the preview must close"
        );
        assert!(seats.is_lone_terminal());
        let after = solved(&seats, viewport, &metrics)
            .get(seats.identity())
            .unwrap()
            .device_rect
            .unwrap();
        assert_eq!(after, before, "closing must return every pixel it borrowed");
    }

    /// A drag hard against either end stops at the two seats' own minimums —
    /// 260 for the terminal and 360 for the preview, which are three
    /// independent lines rather than one line reused (§2.1).
    #[test]
    fn a_divider_drag_stops_at_the_terminal_and_preview_minimums() {
        let metrics = seat_metrics(1_000);
        let viewport = viewport_of(800, 600, 1_000);
        let mut seats = Seats::lone_terminal();
        seats.add_preview(&metrics).expect("the preview seat lands");
        let slot = seats.split_slots(&solved(&seats, viewport, &metrics))[0];

        let (requested, usable) = requested_ratio(
            slot,
            seats.split_reserved(&metrics, slot.id).unwrap(),
            1_000_000,
            -400.0,
        )
        .unwrap();
        seats
            .drag_divider(&metrics, slot.id, requested, usable)
            .expect("dragging to the left edge is feasible, only clamped");
        let terminal = solved(&seats, viewport, &metrics)
            .get(seats.identity())
            .unwrap()
            .rect
            .unwrap();
        assert_eq!(terminal.extent(Axis::Row).floor_px(), 260);

        let (requested, usable) = requested_ratio(
            slot,
            seats.split_reserved(&metrics, slot.id).unwrap(),
            1_000_000,
            1_600.0,
        )
        .unwrap();
        seats
            .drag_divider(&metrics, slot.id, requested, usable)
            .expect("dragging to the right edge is feasible, only clamped");
        let layout = solved(&seats, viewport, &metrics);
        let preview = layout.get(seats.preview().unwrap()).unwrap().rect.unwrap();
        assert_eq!(preview.extent(Axis::Row).floor_px(), 360);
    }

    /// **The ruling, at the seam the app actually uses.** Four terminal columns
    /// want 1043 logical pixels. Dragged to 400, the user gets four narrow panes
    /// tiling the window — not a strip of 24px bars, and not the `fit_what_fits`
    /// error page, which is what the same rectangle produces for the program.
    #[test]
    fn a_narrowed_window_shows_panes_not_bars() {
        let metrics = seat_metrics(1_000);
        let mut seats = Seats::lone_terminal();
        for _ in 0..3 {
            let target = seats.identity();
            seats
                .split_terminal(&metrics, target, Axis::Row, false)
                .expect("a terminal leaf splits");
        }
        let narrow = viewport_of(400, 600, 1_000);

        let by_hand = seats
            .solve(narrow, &metrics, SizePolicy::Sovereign)
            .expect("the user's own window is never refused");
        assert_eq!(by_hand.rects.len(), 4);
        for placement in &by_hand.rects {
            assert_eq!(
                placement.presentation,
                Presentation::Full,
                "{:?} folded in a window the user sized",
                placement.id
            );
            let rect = placement.rect.expect("every seat is presented");
            assert!(rect.right > rect.left, "{:?} has no width", placement.id);
        }
        // Tiling, exactly: four panes and three dividers are the whole viewport.
        let widths: i64 = by_hand
            .presented()
            .map(|(_, rect)| rect.extent(Axis::Row).subpixels())
            .sum();
        assert_eq!(
            widths + 3 * DIVIDER.subpixels(),
            narrow.extent(Axis::Row).subpixels(),
            "a gap here is the seam the ruling forbids"
        );

        // Same tree, same rectangle, program's authority: 260 for the focus plus
        // three 24px bars is 335, so L3 fits it by folding — which is exactly
        // the picture the ruling kept for the program and took from the hand.
        let by_law = seats
            .solve(narrow, &metrics, SizePolicy::Lawful)
            .expect("the ladder reaches 400px by folding");
        let folded = by_law
            .rects
            .iter()
            .filter(|p| matches!(p.presentation, Presentation::Collapsed(_)))
            .count();
        assert_eq!(folded, 3, "the program's own layout still folds");

        // Below the ladder's own floor it is still the honest error, and still
        // only for the program.
        let hopeless = viewport_of(300, 600, 1_000);
        assert!(seats.solve(hopeless, &metrics, SizePolicy::Lawful).is_err());
        assert!(
            seats
                .solve(hopeless, &metrics, SizePolicy::Sovereign)
                .is_ok()
        );
    }

    /// **§7.1.6l — zoom is a viewport posture, not tree surgery.**
    ///
    /// The stage owns the whole viewport, every sibling keeps its place in the
    /// tree and is simply not presented, and the ratios come back bit-identical
    /// on the way out. That last equality is the whole ruling stated as a test:
    /// leaving the parallel layout exactly as it was is not a feature that had
    /// to be written, it is what happens when nothing is done (red line L13).
    ///
    /// Red gate: make `Seats::zoom_pane` touch the tree — a `close_seat` of the
    /// siblings, say — and the `assert_eq!(after, before)` at the end goes red
    /// while every rectangle above it still looks right.
    #[test]
    fn a_zoomed_pane_owns_the_stage_and_lets_it_go_without_rewriting_a_ratio() {
        let metrics = seat_metrics(1_000);
        let viewport = viewport_of(1600, 900, 1_000);
        let mut seats = Seats::lone_terminal();
        let first = seats.identity();
        let second = seats
            .split_terminal(&metrics, first, Axis::Row, false)
            .expect("a terminal leaf splits");
        let before = solved(&seats, viewport, &metrics);
        let tree_before = seats.tree().clone();

        assert!(seats.toggle_zoom(second), "a pane with a sibling zooms");
        assert_eq!(seats.zoom(), Some(second));
        assert_eq!(
            seats.focus(),
            second,
            "the stage takes the focus, or typing goes to a pane nobody can see"
        );
        let staged = solved(&seats, viewport, &metrics);
        assert_eq!(
            staged.get(second).unwrap().rect,
            Some(viewport),
            "the stage is the whole viewport"
        );
        assert!(
            staged.get(first).unwrap().rect.is_none(),
            "a sibling off the stage is not presented"
        );
        assert_eq!(
            staged.rects.len(),
            2,
            "every seat keeps its place in the tree"
        );
        assert_eq!(
            seats.tree(),
            &tree_before,
            "zoom is a viewport posture and touches no node"
        );

        assert!(seats.toggle_zoom(second), "the same gesture lets it go");
        assert_eq!(seats.zoom(), None);
        let after = solved(&seats, viewport, &metrics);
        assert_eq!(after, before, "the parallel layout comes back untouched");
    }

    /// **A zoomed pane keeps its head**, which is what makes both of the verb's
    /// doors survive the zoom: the double-click lands on the head, and the `⌄`
    /// in it opens the menu that carries the way out.
    ///
    /// The head is a fact about the *tree* (`pane_count() > 1`), and zoom does
    /// not touch the tree — so this holds by construction rather than by a
    /// branch. Red gate: make `seat_wears_head` count presented seats instead of
    /// leaves and a zoomed pane loses its head, its menu and its way back.
    #[test]
    fn a_zoomed_pane_still_wears_the_head_both_of_its_doors_hang_off() {
        let metrics = seat_metrics(1_000);
        let mut seats = Seats::lone_terminal();
        let first = seats.identity();
        let second = seats
            .split_terminal(&metrics, first, Axis::Row, false)
            .expect("a terminal leaf splits");
        assert!(seats.toggle_zoom(second));
        assert!(
            seats.seat_wears_head(SeatKind::Terminal),
            "the stage still has a head to double-click"
        );
        assert!(
            !seats.seat_wears_ghost(SeatKind::Terminal, second, None),
            "and therefore no corner ghost — the `⌄` is in the head"
        );
    }

    /// **Any verb that changes the tree lets the zoom go** (§7.1.6l), and it is
    /// one rule in one place: the release rides on the same structural bump the
    /// pane FLIP rides on, so a verb cannot arrive that changes the shape and
    /// forgets to say so.
    ///
    /// Red gate: bump `structure_revision` by hand in any of those verbs instead
    /// of going through `note_structure_change`, and the arm that verb belongs
    /// to goes red.
    #[test]
    fn every_verb_that_changes_the_tree_lets_the_zoom_go() {
        let metrics = seat_metrics(1_000);
        let fresh = || {
            let mut seats = Seats::lone_terminal();
            let first = seats.identity();
            let second = seats
                .split_terminal(&metrics, first, Axis::Row, false)
                .expect("a terminal leaf splits");
            assert!(seats.toggle_zoom(second));
            (seats, first, second)
        };

        let (mut seats, _, stage) = fresh();
        seats
            .split_terminal(&metrics, stage, Axis::Row, false)
            .expect("the stage splits");
        assert_eq!(seats.zoom(), None, "a split let the zoom go");

        let (mut seats, sibling, _) = fresh();
        assert!(seats.close_seat(&metrics, sibling));
        assert_eq!(seats.zoom(), None, "a close let the zoom go");

        let (mut seats, _, _) = fresh();
        seats.add_preview(&metrics).expect("the preview seat lands");
        assert_eq!(seats.zoom(), None, "an arriving preview let the zoom go");

        // A divider drag is *not* in that set, and must not be: it steers a ratio
        // and changes no pane's existence. It is also the one verb a zoomed tab
        // cannot be asked for from the glass — there is no divider on screen —
        // which is why it is asked for here directly.
        let (mut seats, _, stage) = fresh();
        let viewport = viewport_of(1600, 900, 1_000);
        let tiled = solve(
            seats.tree(),
            viewport,
            &metrics,
            seats.focus(),
            LayoutMode::Parallel,
            SizePolicy::Lawful,
        )
        .expect("the tiled tree fits");
        let slot = seats.split_slots(&tiled)[0];
        let (requested, usable) = requested_ratio(
            slot,
            seats.split_reserved(&metrics, slot.id).unwrap(),
            1_000_000,
            120.0,
        )
        .unwrap();
        seats
            .drag_divider(&metrics, slot.id, requested, usable)
            .expect("the drag is feasible");
        assert_eq!(
            seats.zoom(),
            Some(stage),
            "steering a ratio is not a change of shape"
        );
    }

    /// User ruling 2026-08-08. Was
    /// `a_divider_drag_in_a_window_too_small_for_both_seats_is_refused`: a 499px
    /// slot cannot hold a 260 terminal beside a 360 preview, and the drag used
    /// to die under the hand for saying so. The window is the user's, and so is
    /// the divider in it.
    #[test]
    fn a_divider_drag_in_a_window_too_small_for_both_seats_still_follows_the_hand() {
        let metrics = seat_metrics(1_000);
        let mut seats = Seats::lone_terminal();
        seats.add_preview(&metrics).expect("the preview seat lands");
        let viewport = viewport_of(1600, 900, 1_000);
        let slot = seats.split_slots(&solved(&seats, viewport, &metrics))[0];
        let cramped = LogicalPx::px(499);
        let origin = seats.tree().ratios()[0].1;
        // 260 + 360 wants 620 of a 499px slot, so *every* ratio was infeasible
        // by the old rule and the divider was dead for the whole gesture.
        let aimed = Ratio::from_ppm(800_000).unwrap();
        assert_eq!(
            seats.drag_divider(&metrics, slot.id, aimed, cramped),
            Ok(true),
            "620px of demand in a 499px slot is a narrow pane, not an error"
        );
        assert_eq!(
            seats.tree().ratios()[0].1,
            aimed,
            "and it went where it was aimed"
        );

        // Esc restores through the same edit, from wherever the drag reached.
        assert_eq!(
            seats.drag_divider(&metrics, slot.id, origin, cramped),
            Ok(true)
        );
        assert_eq!(
            seats.tree().ratios()[0].1,
            origin,
            "Esc puts the one ratio back"
        );
    }

    /// **A8 — a files column takes the whole left edge, not a slice of the
    /// focused pane.**
    ///
    /// `addFilesPane` is `splitRootOf(w, "left")` and pointedly not
    /// `splitLeafIn` (mock-up 3701-3706): however many panes the tab already
    /// holds, the tree runs the full height of the window rather than being
    /// squeezed into whichever pane had the keyboard. "That is also the natural
    /// shape of a file sidebar."
    ///
    /// Red gate: build it with `SplitSeat` on the focused seat and the column
    /// stops being full height the moment the tab holds a horizontal split.
    #[test]
    fn a_files_pane_takes_the_whole_left_edge_however_many_panes_are_already_there() {
        let dpi_milli = 1_000;
        let metrics = seat_metrics(dpi_milli);
        let viewport = viewport_of(1600, 900, dpi_milli);
        let mut seats = Seats::lone_terminal();
        // A tab already cut across, so "the whole left edge" is a different
        // rectangle from "the left half of the focused pane".
        seats
            .split_terminal(&metrics, seats.identity(), Axis::Col, false)
            .expect("a lone terminal splits");

        let column = seats
            .add_files_pane(&metrics, None)
            .expect("a files column fits beside two stacked terminals");
        let layout = solved(&seats, viewport, &metrics);
        let column_rect = layout
            .get(column)
            .and_then(|placement| placement.rect)
            .expect("the column is on screen");

        assert_eq!(
            column_rect.near(Axis::Col),
            viewport.near(Axis::Col),
            "the column starts at the top of the viewport"
        );
        assert_eq!(
            column_rect.extent(Axis::Col),
            viewport.extent(Axis::Col),
            "and runs its whole height — a rim drop, not a split of one pane"
        );
        assert_eq!(
            column_rect.near(Axis::Row),
            viewport.near(Axis::Row),
            "and it is the leading column"
        );
        assert_eq!(
            column_rect.extent(Axis::Row),
            FILES_W,
            "wearing its kind's opening width"
        );
        // Both terminals are still there, narrowed rather than displaced.
        assert_eq!(seats.terminals().len(), 2);
        assert_eq!(seats.files(), vec![column]);
    }

    /// **F66/F70 — the files column drags in pixels, and Esc puts back the one
    /// width it moved.**
    ///
    /// The pixel half of §3.4. Two things are being pinned at once and both
    /// matter: that the gesture writes a `fixed_extent` rather than a ratio, and
    /// that the *ratios of the tree are bit-identical before and after* — a
    /// pixel drag has an empty focus set, so theorem N says nothing else moved.
    /// A drag that quietly rewrote the ratio beside it would look right on the
    /// frame it happened and wrong on the next window resize.
    ///
    /// Red gate: point the gesture at `drag_divider` instead and the width stays
    /// at 240 while a ratio moves — which is the exact failure "a fixed column
    /// stops being fixed" describes.
    #[test]
    fn a_files_column_drag_writes_pixels_and_esc_puts_the_width_back() {
        let dpi_milli = 1_000;
        let metrics = seat_metrics(dpi_milli);
        let viewport = viewport_of(1600, 900, dpi_milli);
        let mut seats = Seats::lone_terminal();
        let column = seats.add_files_pane(&metrics, None).expect("a column fits");
        let ratios_before = seats.tree().ratios();
        let origin = seats.fixed_extent_of(column).unwrap_or(FILES_W);

        let slot = seats.split_slots(&solved(&seats, viewport, &metrics))[0];
        let (seat, leading) = seats
            .fixed_column_of_split(&metrics, slot.id)
            .expect("the split has a bare fixed column on one side");
        assert_eq!(seat, column);
        assert!(leading, "the column was seated at the leading edge");

        // A pointer at 320 logical pixels, which is nobody's default.
        let (requested, usable) =
            requested_fixed_extent(slot, leading, scale_ppm(dpi_milli), 320.0)
                .expect("the slot has room");
        assert!(
            seats
                .drag_fixed_extent(&metrics, slot.id, requested, usable)
                .expect("a bare fixed leaf accepts the drag")
        );
        assert_eq!(
            seats.fixed_extent_of(column),
            Some(LogicalPx::px(320)),
            "the width goes where the hand went"
        );
        assert_eq!(
            seats.tree().ratios(),
            ratios_before,
            "L9/theorem N: a pixel drag rewrites no ratio at all"
        );

        // Esc: back through the same edit, which is what makes the rollback ask
        // the current clamp rather than trusting a width that fitted a window
        // that may since have changed.
        assert!(
            seats
                .drag_fixed_extent(&metrics, slot.id, origin, usable)
                .expect("the restore is the same edit")
        );
        assert_eq!(
            seats.fixed_extent_of(column),
            Some(origin),
            "F70: Esc restores the width, not a ratio"
        );
        assert_eq!(seats.tree().ratios(), ratios_before);
    }

    /// **Where the hand stops being obeyed: `FILES_W_MIN` is a floor on the
    /// *solve*, even though it is not a clamp on the *edit*.**
    ///
    /// Recorded rather than asserted as desirable, because the two halves of
    /// `bt-layout` currently say different things and this slice is not the
    /// place to overturn either:
    ///
    /// * `edit.rs` clamps a fixed drag to `[0, usable]` and says in as many
    ///   words that "a hand that keeps pulling past it is entitled to a narrower
    ///   column" — the 2026-08-08 Sovereign ruling, which took the minima out of
    ///   the user's way.
    /// * `tree.rs`'s `Seat::fixed_width` answers `max(fixed_extent, min_row)`,
    ///   so the solver lays the column out at 170 no matter how much narrower
    ///   the stored width is.
    ///
    /// The stored value therefore goes where the hand went and the *picture*
    /// stops at 170. Everything stays self-consistent across a save and reload —
    /// the width is carried, and re-solving it gives the same 170 — so nothing
    /// here is broken today; what is unresolved is whether §2.3's `max` outranks
    /// the Sovereign revision, and that is a ruling, not a bug fix.
    ///
    /// This pin exists so the answer cannot change silently: if the floor is
    /// ever relaxed, this test fails and says which of the two rules moved.
    #[test]
    fn a_files_column_dragged_under_its_floor_stores_the_hand_and_draws_the_floor() {
        let dpi_milli = 1_000;
        let metrics = seat_metrics(dpi_milli);
        let viewport = viewport_of(1600, 900, dpi_milli);
        let mut seats = Seats::lone_terminal();
        let column = seats.add_files_pane(&metrics, None).expect("a column fits");
        let slot = seats.split_slots(&solved(&seats, viewport, &metrics))[0];
        let (_, leading) = seats
            .fixed_column_of_split(&metrics, slot.id)
            .expect("a bare fixed column");

        // 90 logical pixels — well under the 170 the column would like.
        let (requested, usable) = requested_fixed_extent(slot, leading, scale_ppm(dpi_milli), 90.0)
            .expect("the slot has room");
        seats
            .drag_fixed_extent(&metrics, slot.id, requested, usable)
            .expect("the edit accepts it");

        assert_eq!(
            seats.fixed_extent_of(column),
            Some(LogicalPx::px(90)),
            "the edit stores what the hand asked for: no floor in `[0, usable]`"
        );
        let drawn = solved(&seats, viewport, &metrics)
            .get(column)
            .and_then(|placement| placement.rect)
            .expect("the column is on screen")
            .extent(Axis::Row);
        assert_eq!(
            drawn,
            bt_layout::FILES_W_MIN,
            "but the solve holds it to `max(fixed_extent, FILES_W_MIN)` — the \
             open question named in this test's own doc"
        );
    }

    /// **§3.4 — a fixed subtree that is not a bare leaf has no single width to
    /// drag, and the gesture finds that out before it starts.**
    ///
    /// Two files columns stacked share a slot but not a width, and the honest
    /// answer is to refuse rather than to write a share into a fixed slot. The
    /// point of asking *here* — in the same reading the pointer uses to choose
    /// its verb — is that the refusal happens at button-down, so the drag never
    /// begins, instead of beginning and silently doing nothing for its whole
    /// length.
    #[test]
    fn a_stacked_pair_of_files_columns_offers_the_pointer_no_width_to_drag() {
        let dpi_milli = 1_000;
        let metrics = seat_metrics(dpi_milli);
        let viewport = viewport_of(1600, 900, dpi_milli);
        // Built through `from_persisted` because `Seats` has no verb that stacks
        // two files columns — which is itself the point: this shape is one a
        // saved document can hold and a gesture cannot make, so the persisted
        // path is both the honest way to reach it and the way it will actually
        // arrive in the wild.
        let files_leaf = |width: u32| {
            Box::new(LayoutNodeV1::Leaf(LeafNodeV1::Files(
                bt_persist::FilesLeafV1 {
                    view: bt_persist::FilesViewV1::Files,
                    root: String::new(),
                    open: Vec::new(),
                    sel: None,
                    width,
                    remotes_open: false,
                },
            )))
        };
        let seats = Seats::from_persisted(&LayoutNodeV1::Split(SplitNodeV1 {
            dir: SplitDirV1::Row,
            ratio: 300_000,
            children: [
                // Two files columns stacked: a fixed *subtree*, not a fixed leaf.
                Box::new(LayoutNodeV1::Split(SplitNodeV1 {
                    dir: SplitDirV1::Col,
                    ratio: 500_000,
                    children: [files_leaf(240), files_leaf(200)],
                })),
                Box::new(LayoutNodeV1::Leaf(LeafNodeV1::Term(TermLeafV1 {
                    profile_id: "pwsh".to_owned(),
                    cwd: String::new(),
                    manual_name: None,
                    card_skip: 0,
                }))),
            ],
        }));

        let layout = solved(&seats, viewport, &metrics);
        let root = seats.split_slots(&layout)[0];
        assert_eq!(
            seats.fixed_column_of_split(&metrics, root.id),
            None,
            "no single width to drag, so the pointer takes the ratio grip and \
             `bt-layout` refuses the pixel edit for the same reason"
        );
    }

    /// Save, "restart", reload: the tree comes back and solves to the same
    /// rectangles. What crossed the disk was intent — shape, direction, and a
    /// `u32` ppm ratio — and never a rectangle (red line L11).
    #[test]
    fn a_saved_seat_tree_reloads_to_the_same_rects() {
        let dpi_milli = 1_250;
        let metrics = seat_metrics(dpi_milli);
        let viewport = viewport_of(1600, 900, dpi_milli);
        let mut seats = Seats::lone_terminal();
        seats.add_preview(&metrics).expect("the preview seat lands");
        // Drag to a ratio that is nobody's default, so a round trip cannot pass
        // by landing back on a constant.
        let slot = seats.split_slots(&solved(&seats, viewport, &metrics))[0];
        let (requested, usable) = requested_ratio(
            slot,
            seats.split_reserved(&metrics, slot.id).unwrap(),
            scale_ppm(dpi_milli),
            913.0,
        )
        .unwrap();
        seats
            .drag_divider(&metrics, slot.id, requested, usable)
            .unwrap();
        let ratio_before = seats.tree().ratios();
        assert_ne!(
            ratio_before[0].1,
            Ratio::HALF,
            "the drag must have moved it"
        );
        let before = solved(&seats, viewport, &metrics).logical_rects();

        let session = SessionV1 {
            schema_version: SESSION_SCHEMA_VERSION,
            windows: vec![bt_persist::SessionWindowV1 {
                tabs: vec![TabV1 {
                    // Every leaf answers the same here on purpose: this pin is
                    // about the tree's shape surviving the round trip, and a
                    // per-seat answer would be noise in it.
                    root: seats.to_persisted(
                        &|_| TermLeafV1 {
                            profile_id: "pwsh".to_owned(),
                            cwd: String::new(),
                            manual_name: None,
                            card_skip: 0,
                        },
                        &|_| FilesLeafState::default(),
                    ),
                    pinned: false,
                    focused_leaf: "leaf-0".to_owned(),
                    preview: None,
                }],
                ..bt_persist::SessionWindowV1::default()
            }],
            ..SessionV1::default()
        };
        let dir = std::env::temp_dir().join(format!("bt-app-seats-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("session.json");
        write_session_atomic(&path, &session).unwrap();

        let (loaded, _report, degradation) = read_session(&path);
        assert!(
            degradation.is_clean(),
            "a tree this build wrote must reload without degrading"
        );
        let restored = Seats::from_persisted(&loaded.windows[0].tabs[0].root);
        assert_eq!(
            restored.tree().ratios().len(),
            ratio_before.len(),
            "the shape survived"
        );
        assert_eq!(
            restored.tree().ratios()[0].1.ppm(),
            ratio_before[0].1.ppm(),
            "the ppm ratio crossed the disk unchanged — a float or a rounded \
             decimal would land somewhere near here instead of here"
        );
        assert_eq!(
            solved(&restored, viewport, &metrics).logical_rects(),
            before,
            "the same intent solves to the same picture"
        );
        assert!(
            restored.preview().is_some(),
            "the preview seat is a seat again"
        );
        std::fs::remove_dir_all(&dir).unwrap();
    }

    /// A window too narrow for both seats collapses the non-focus one into a
    /// clickable bar that keeps its place in the tree (§2.6.3) — and the bar is
    /// real chrome with a real hit target, not an absence.
    ///
    /// Opening the preview must be indistinguishable, downstream, from a window
    /// narrowing that leaves the terminal the same rectangle.
    ///
    /// Everything the resize machinery is handed — the grid, and the pixel size
    /// ConPTY is told — is a function of the terminal seat's rectangle and
    /// nothing else (`grid_for_pixels(seat)`, `terminal_pty_physical(seat)`), so
    /// the pin is that the rectangle a preview leaves the terminal is *exactly*
    /// the rectangle a lone leaf gets from a window of that size. If that holds
    /// at every DPI, the two paths cannot hand the coalescer different numbers,
    /// and there is no seat-shaped resize for anything downstream to notice.
    ///
    /// Red gate: derive the second rectangle from the *window* rather than from
    /// the seat — the discrepancy the bug report described — and the equality
    /// fails at every DPI.
    #[test]
    fn opening_the_preview_hands_the_resize_machinery_a_window_narrowings_rectangle() {
        for dpi_milli in [1_000u32, 1_250, 1_500, 1_750, 2_000, 2_500] {
            let metrics = seat_metrics(dpi_milli);
            let (width, height) = (1920u32, 1200u32);

            let mut seats = Seats::lone_terminal();
            seats.add_preview(&metrics).expect("the preview must open");
            let opened = seat_viewport(
                &solved(&seats, viewport_of(width, height, dpi_milli), &metrics),
                seats.identity(),
            )
            .expect("the terminal keeps a rectangle");
            assert!(
                opened.width < width,
                "the preview must actually cost the terminal width at {dpi_milli} milli-DPI"
            );

            // The same rectangle, reached by narrowing the window instead.
            let narrowed = seat_viewport(
                &solved(
                    &Seats::lone_terminal(),
                    viewport_of(opened.width, height, dpi_milli),
                    &metrics,
                ),
                SeatId(1),
            )
            .expect("a lone leaf keeps a rectangle");
            let expected = seats_surface(opened.width, height, dpi_milli);
            assert_eq!(narrowed, expected);
            assert_eq!(
                (narrowed.width, narrowed.height),
                (opened.width, opened.height),
                "the two paths must present the same extent to `grid_for_pixels` \
                 and to the ConPTY pixel size at {dpi_milli} milli-DPI"
            );
            // Red gate: the window's extent is not that extent, so an
            // implementation that read it would be caught here.
            assert_ne!(
                (width, height),
                (opened.width, opened.height),
                "the pin would pass even if the grid were derived from the window"
            );

            // Closing hands every pixel back, so the sequence is symmetric.
            let preview = seats.preview().expect("the preview seat is open");
            assert!(
                seats.close_seat(&metrics, preview),
                "the preview must close"
            );
            let closed = seat_viewport(
                &solved(&seats, viewport_of(width, height, dpi_milli), &metrics),
                seats.identity(),
            )
            .expect("the terminal keeps a rectangle");
            assert_eq!(closed, seats_surface(width, height, dpi_milli));
        }
    }

    /// This state is deliberately hard to reach by dragging the window, because
    /// §2.6.5's minimum inner size stops the OS well above it; that is the
    /// concession chain being a degradation path rather than an everyday one.
    /// It is reachable when the OS ignores the hint (tiny-window §4.3), so it is
    /// pinned here rather than left to a gesture nobody can perform.
    #[test]
    fn a_squeezed_seat_becomes_a_clickable_bar_that_keeps_its_place() {
        let metrics = seat_metrics(1_000);
        let mut seats = Seats::lone_terminal();
        seats.add_preview(&metrics).expect("the preview seat lands");
        // 260 + 1 + 360 needs 621; 500 does not have it, so the non-focus seat
        // collapses and the focus seat is the last to fall.
        let viewport = viewport_of(500, 600, 1_000);
        let layout = seats
            .solve(viewport, &metrics, SizePolicy::Lawful)
            .expect("L3 must satisfy 500px");
        let preview = seats.preview().unwrap();
        assert!(
            matches!(
                layout.get(preview).unwrap().presentation,
                Presentation::Collapsed(_)
            ),
            "the non-focus seat is the one that gives way"
        );
        assert_eq!(
            layout.get(seats.identity()).unwrap().presentation,
            Presentation::Full,
            "W2: the focus seat falls last"
        );
        assert_eq!(
            layout.get(preview).unwrap().rect.unwrap().extent(Axis::Row),
            bt_layout::COLLAPSED_EXTENT
        );

        let (quads, _labels, _sprites) =
            build_chrome(&seats, &layout, 1.0, ChromePointer::default());
        assert!(
            quads
                .iter()
                .any(|quad| quad.color == chrome_palette().collapse_bar),
            "a collapsed seat is drawn as a bar"
        );
        let bar = layout.get(preview).unwrap().device_rect.unwrap();
        assert_eq!(
            hit_chrome(
                &seats,
                &layout,
                1.0,
                None,
                f64::from((bar.left + bar.right) as i32) / 2.0,
                f64::from((bar.top + bar.bottom) as i32) / 2.0,
            ),
            Some(ChromeTarget::CollapseBar(preview)),
            "the whole strip is clickable"
        );
        assert!(
            seats.tree().find_seat(preview).is_some(),
            "W1: collapsing is a presentation, never an edit"
        );
    }

    /// PIN (modal): with the settings dialog up, the three things a press in
    /// this window can otherwise reach — a divider, another seat's bar, the
    /// terminal's own rectangle — are all the scrim's.
    ///
    /// Red gate: each point is first shown to be the thing it claims to be, by
    /// the very functions the router consults (`hit_chrome`, `pane_at`).
    /// Without that half the assertions would pass over any three points at all,
    /// including three that are inside the dialog.
    #[test]
    fn a_modal_swallows_the_divider_the_seat_and_the_terminal_under_it() {
        let metrics = seat_metrics(1_000);
        let mut seats = Seats::lone_terminal();
        seats.add_preview(&metrics).expect("the preview seat lands");
        // Tall enough that all three probe points land *outside* the dialog,
        // which is the case this pins: a press the panel itself catches already
        // lands nowhere (`SettingsTarget::Panel => {}`), so it would prove the
        // scrim nothing. The dialog is top-anchored and grows with its row list,
        // so this window has to stay ahead of that list — 800px stopped clearing
        // the divider the moment the second formula row was added, and 1200
        // stopped the moment the Git panel's switch arrived under it.
        let (width, height) = (1_280u32, 1_400u32);
        let layout = solved(&seats, viewport_of(width, height, 1_000), &metrics);
        let rows = crate::settings::visible_rows(TabLayoutMode::Horizontal);
        let overlay = crate::settings::layout_for_menu(
            width as f32,
            height as f32,
            1.0,
            None,
            None,
            crate::settings::SettingsContent {
                advanced_reveal: None,
                rows: &rows,
                shortcuts: &[],
                profiles: &[],
                scheme_files: &[],
                advanced: crate::settings::AdvancedOpen::default(),
                editor: None,
                values: Box::leak(Box::new(crate::settings::SettingsValues::sample())),
            },
            crate::settings::SettingsCategory::Appearance,
            0.0,
            0.0,
            &mut |_, _| 0.0,
        )
        .expect("this window hosts the dialog");

        let slot = seats
            .split_slots(&layout)
            .into_iter()
            .next()
            .expect("two seats have a divider between them");
        let divider = (
            f64::from((slot.band[0] + slot.band[2]) / 2.0),
            f64::from((slot.band[1] + slot.band[3]) / 2.0),
        );
        let preview = seats.preview().expect("the preview seat is open");
        let head = layout.get(preview).unwrap().device_rect.unwrap();
        let seat = (
            f64::from((head.left + head.right) as i32) / 2.0,
            f64::from(head.top as i32) + 8.0,
        );
        let terminal_rect = layout
            .get(seats.identity())
            .unwrap()
            .device_rect
            .expect("the terminal seat has a rectangle");
        let terminal = (
            f64::from((terminal_rect.left + terminal_rect.right) as i32) / 2.0,
            f64::from(terminal_rect.bottom as i32) - 8.0,
        );

        assert_eq!(
            hit_chrome(&seats, &layout, 1.0, None, divider.0, divider.1),
            Some(ChromeTarget::Divider(slot.id)),
            "the first point really is a divider"
        );
        assert_eq!(
            hit_chrome(&seats, &layout, 1.0, Some(preview), seat.0, seat.1),
            Some(ChromeTarget::PaneHeader(preview)),
            "the second point really is another seat's head"
        );
        assert_eq!(
            pane_at(&layout, terminal.0, terminal.1),
            Some(seats.identity()),
            "the third point really is inside the terminal"
        );

        for (what, (x, y)) in [
            ("the divider", divider),
            ("the seat head", seat),
            ("the terminal", terminal),
        ] {
            // Scrim **or** Panel, and the pair is the whole answer: the dialog
            // grew past these three points when the Appearance page took the
            // window's ground (§7.1.6c-4b), so a chrome point that used to sit
            // beside the dialog now sits under it. Both are "the modal owns this
            // pixel" — the scrim closes on a press and the panel does nothing —
            // and neither is the divider, the head or the terminal that
            // `hit_chrome` just proved is really there.
            let over =
                crate::settings::hit(&overlay, &crate::settings::SettingsValues::sample(), x, y);
            assert!(
                matches!(
                    over,
                    crate::settings::SettingsTarget::Scrim | crate::settings::SettingsTarget::Panel
                ),
                "a modal means MODAL: {what} answers the dialog and not the window ({over:?})"
            );
        }
    }

    /// An unknown leaf kind stays visible as a placeholder rather than being
    /// quietly turned into a terminal (§5 constraint 2).
    #[test]
    fn an_unknown_persisted_leaf_reloads_as_a_visible_placeholder() {
        let node = LayoutNodeV1::Split(SplitNodeV1 {
            dir: SplitDirV1::Row,
            ratio: 600_000,
            children: [
                Box::new(LayoutNodeV1::Leaf(LeafNodeV1::Term(TermLeafV1 {
                    profile_id: "pwsh.exe".to_owned(),
                    cwd: String::new(),
                    manual_name: None,
                    card_skip: 0,
                }))),
                Box::new(LayoutNodeV1::Leaf(LeafNodeV1::Unknown)),
            ],
        });
        let seats = Seats::from_persisted(&node);
        let kinds: Vec<_> = seats
            .tree()
            .seats_in_order()
            .into_iter()
            .map(|seat| seat.kind)
            .collect();
        assert_eq!(kinds, vec![SeatKind::Terminal, SeatKind::Placeholder]);
    }

    /// The chrome at one DPI, with a preview open so the terminal wears a head.
    fn chrome_at(dpi_milli: u32) -> (Vec<ChromeLabel>, Vec<ChromeSprite>) {
        let metrics = seat_metrics(dpi_milli);
        let mut seats = Seats::lone_terminal();
        seats.add_preview(&metrics).expect("the preview seat lands");
        let layout = solved(&seats, viewport_of(1600, 900, dpi_milli), &metrics);
        let (_, labels, sprites) = build_chrome_with_preview(
            &seats,
            &layout,
            dpi_milli as f32 / 1000.0,
            ChromePointer::default(),
            None,
            None,
            None,
        );
        (labels, sprites)
    }

    fn vertical_centre(rect: [f32; 4]) -> f32 {
        (rect[1] + rect[3]) / 2.0
    }

    /// PIN — the active tab's mark and its title hang off one axis.
    ///
    /// `.tab { display: flex; align-items: center }` in the mock-up: the mark box
    /// and the title share the tab's own centre line. Both are placed from that
    /// centre with the *same* rounding — the mark's box is rounded to whole
    /// physical pixels so its texture lands on the grid, and the title's rect is
    /// the tab itself — so no DPI can open a step between them by rounding one
    /// down and the other up.
    #[test]
    fn tab_mark_and_title_share_one_vertical_axis() {
        for dpi_milli in [1_000u32, 1_250, 1_500, 2_000] {
            let (labels, sprites) = chrome_at(dpi_milli);
            let title_bar = WINDOW_TITLE_BAR_LOGICAL_PX * dpi_milli as f32 / 1000.0;
            let mark = sprites
                .iter()
                .find(|sprite| {
                    sprite.mark == ChromeMark::ProfilePowerShell && sprite.rect[3] <= title_bar
                })
                .expect("the active tab wears the session's profile mark");
            let title = labels
                .iter()
                .find(|label| label.text == "PowerShell")
                .expect("the active tab carries its session's name");
            let delta = vertical_centre(mark.rect) - vertical_centre(title.rect);
            assert!(
                delta.abs() <= 0.5,
                "tab mark and title off one axis by {delta} physical px at {dpi_milli} milli-DPI \
                 (mark {:?}, title {:?})",
                mark.rect,
                title.rect
            );
        }
    }

    #[test]
    fn tab_title_uses_session_text_or_the_profile_fallback() {
        let metrics = seat_metrics(1_000);
        let seats = Seats::lone_terminal();
        let layout = solved(&seats, viewport_of(1600, 900, 1_000), &metrics);

        let (_, titled, _) = build_chrome_with_preview(
            &seats,
            &layout,
            1.0,
            ChromePointer::default(),
            Some("Claude ✳ 任务"),
            None,
            None,
        );
        assert!(titled.iter().any(|label| label.text == "Claude ✳ 任务"));

        let (_, fallback, _) = build_chrome_with_preview(
            &seats,
            &layout,
            1.0,
            ChromePointer::default(),
            None,
            None,
            None,
        );
        assert!(fallback.iter().any(|label| label.text == "PowerShell"));
    }

    /// PIN — R1/A5: **`.panel-toggle` is drawn, hit and measured from one box,
    /// and only the expanded vertical bar has one.**
    ///
    /// The mock-up's three-line gate, as three answers (906-913): `display: none`
    /// by default, `flex` under `[data-tabs="vertical"]`, and back to `none`
    /// under `.rail-icons` — *"in icon mode the sidebar is already parked —
    /// nothing left to collapse"*. A horizontal bar must not merely fail to draw
    /// it; the box has to be absent, or the pointer would find a button nobody
    /// painted.
    ///
    /// The numbers are the mock-up's own: a 30x26 box at the bar's 12px inset,
    /// centred in a 40px bar, which puts it at `[12, 7, 42, 33]`.
    ///
    /// Red gate: drop the `mode == Icons` clause and the icon rail grows a button
    /// it has nothing to do with; drop the `layout != Vertical` clause and the
    /// horizontal bar answers `PanelToggle` where its first tab stands.
    #[test]
    fn the_panel_toggle_stands_only_on_the_expanded_vertical_bar() {
        let expanded = RailState {
            layout: TabLayoutMode::Vertical,
            mode: RailMode::Expanded,
            ..RailState::default()
        };
        let icons = RailState {
            mode: RailMode::Icons,
            ..expanded
        };
        let horizontal = RailState::default();

        assert_eq!(
            panel_toggle_box(1.0, expanded),
            Some([12.0, 7.0, 42.0, 33.0]),
            "`.panel-toggle` is 30x26 at the bar's 12px inset, centred in 40px"
        );
        assert_eq!(
            panel_toggle_box(1.0, horizontal),
            None,
            "no toggle on a strip"
        );
        assert_eq!(
            panel_toggle_box(1.0, icons),
            None,
            "an icon rail is already parked, so there is nothing left to collapse"
        );
        // A fold does not take the button away with it — a toggle that vanished
        // when pressed could never be pressed back.
        assert_eq!(
            panel_toggle_box(
                1.0,
                RailState {
                    collapsed: true,
                    ..expanded
                }
            ),
            Some([12.0, 7.0, 42.0, 33.0]),
            "the toggle survives its own verb"
        );

        for scale in [1.0_f32, 1.25, 1.5, 2.0] {
            let width = 960.0 * scale;
            let toggle = panel_toggle_box(scale, expanded).expect("the expanded bar carries one");
            assert_eq!(
                window_chrome_boxes(width, scale, expanded).first(),
                Some(&(ChromeTarget::PanelToggle, toggle)),
                "it leads the run: `.drag`'s first child, at the far left"
            );
            // Drawn, hit and measured from one box.
            assert_eq!(
                hit_window_chrome(
                    width,
                    scale,
                    expanded,
                    f64::from((toggle[0] + toggle[2]) / 2.0),
                    f64::from((toggle[1] + toggle[3]) / 2.0),
                ),
                Some(ChromeTarget::PanelToggle),
                "{scale}x"
            );
            // The horizontal bar does not answer at the same point.
            assert_ne!(
                hit_window_chrome(
                    width,
                    scale,
                    horizontal,
                    f64::from((toggle[0] + toggle[2]) / 2.0),
                    f64::from((toggle[1] + toggle[3]) / 2.0),
                ),
                Some(ChromeTarget::PanelToggle),
                "a horizontal bar draws no toggle, so it cannot be hit at {scale}x"
            );
            assert!(
                !window_chrome_boxes(width, scale, icons)
                    .iter()
                    .any(|(target, _)| *target == ChromeTarget::PanelToggle),
                "nor does an icon rail at {scale}x"
            );
            // A4 — the name stands after the toggle and its 8px gap, and at the
            // bar's own inset when there is no toggle to stand after.
            assert_eq!(
                app_title_left_px(scale, expanded),
                toggle[2] + (8.0 * scale).round(),
                "`.apptitle` follows the toggle across `.drag`'s gap at {scale}x"
            );
            assert_eq!(
                app_title_left_px(scale, icons),
                (WINDOW_TAB_PADDING_LEFT_LOGICAL_PX * scale).round(),
                "with no toggle the name takes the bar's own inset at {scale}x"
            );
        }
    }

    /// PIN — R3: **the window's drag boundary answers to the layout, not to a tab
    /// strip that is no longer in the bar.**
    ///
    /// The number under test is the only thing bt-platform's `WM_NCHITTEST`
    /// bridge knows about the title bar: left of it is `HTCLIENT`, right of it is
    /// `HTCAPTION`. With the tabs down the side the bar holds one button and a
    /// label, so the app's run ends at the button — the label is inside `.drag`
    /// and a title has always been part of the handle.
    ///
    /// **Tab count is the witness.** The bug was a horizontal-strip formula asked
    /// in the vertical layout, and a strip's answer *grows* with the number of
    /// tabs until it claims the whole run. So the assertion that matters is that
    /// thirty tabs move this number not at all when the tabs are in the rail —
    /// under the old code they moved it to nearly the window's width, and the
    /// entire top bar stopped being draggable.
    ///
    /// Red gate: route the vertical arm back through `tab_strip_right_px` and the
    /// thirty-tab case reports a strip-shaped boundary instead of 42.
    #[test]
    fn the_drag_boundary_follows_the_tabs_off_the_title_bar() {
        let expanded = RailState {
            layout: TabLayoutMode::Vertical,
            mode: RailMode::Expanded,
            ..RailState::default()
        };
        let icons = RailState {
            mode: RailMode::Icons,
            ..expanded
        };
        let horizontal = RailState::default();
        let (width, scale) = (960.0_f32, 1.0_f32);

        for tabs in [1_usize, 2, 30] {
            assert_eq!(
                title_bar_app_run_right_px(width, scale, tabs, expanded),
                42,
                "the app owns the toggle and nothing else, whatever {tabs} tabs \
                 would have done to a strip"
            );
            assert_eq!(
                title_bar_app_run_right_px(width, scale, tabs, icons),
                0,
                "an icon rail puts nothing in the bar at all, so all of it drags"
            );
            assert_eq!(
                title_bar_app_run_right_px(width, scale, tabs, horizontal),
                tab_strip_right_px(width, scale, tabs),
                "the horizontal bar's answer is unchanged: it really does hold a \
                 strip"
            );
        }
        // The witness itself: a strip's boundary grows with its tabs, which is
        // exactly the growth that used to leak into the vertical layout.
        assert!(
            tab_strip_right_px(width, scale, 30)
                > title_bar_app_run_right_px(width, scale, 30, expanded),
            "a thirty-tab strip claims far more of the bar than the toggle does"
        );
    }

    /// The caption run's boxes and its hit test are one arithmetic, and this is
    /// what says so: every box answers with its own target when asked at its
    /// centre, and the run tiles the corner with no seam between the buttons.
    ///
    /// The tooltip anchors on these boxes; a second `width - 4 * button` would
    /// stay right until the day it did not, and the symptom would be a tip
    /// labelled "Maximize" standing under the close button.
    #[test]
    fn the_caption_boxes_are_the_boxes_the_caption_hit_test_answers_from() {
        // The horizontal bar, whose whole app-owned run in the caption corner is
        // these four — the vertical one's fifth box has its own test.
        let rail = RailState::default();
        for scale in [1.0_f32, 1.25, 1.5, 2.0] {
            let width = 960.0 * scale;
            let boxes = window_caption_boxes(width, scale);
            assert_eq!(
                window_chrome_boxes(width, scale, rail),
                boxes.to_vec(),
                "a horizontal bar carries no panel toggle, so the run is the \
                 caption run and nothing else"
            );
            assert_eq!(
                boxes.map(|(target, _)| target),
                [
                    ChromeTarget::Settings,
                    ChromeTarget::Minimize,
                    ChromeTarget::Maximize,
                    ChromeTarget::CloseWindow,
                ],
                "the gear leads the run"
            );
            for (target, rect) in boxes {
                assert_eq!(
                    hit_window_chrome(
                        width,
                        scale,
                        rail,
                        f64::from((rect[0] + rect[2]) / 2.0),
                        f64::from((rect[1] + rect[3]) / 2.0),
                    ),
                    Some(target),
                    "{target:?} at {scale}x"
                );
            }
            // No seam: each box begins where the last one ended, and the run
            // finishes hard against the window's own edge — the corner pixel
            // belongs to `close` at every scale.
            for pair in boxes.windows(2) {
                assert!((pair[0].1[2] - pair[1].1[0]).abs() < 1e-4, "{pair:?}");
            }
            assert!((boxes[3].1[2] - width).abs() < 1e-4);
            assert_eq!(
                hit_window_chrome(width, scale, rail, f64::from(width) - 0.5, 1.0),
                Some(ChromeTarget::CloseWindow)
            );
            // And nothing to the left of the run is the run's.
            assert_eq!(
                hit_window_chrome(width, scale, rail, f64::from(boxes[0].1[0]) - 1.0, 1.0),
                None
            );
        }
    }

    /// PIN — **the band between the `⌄` and the gear sends this window nothing
    /// at all** (user report, 2026-08-21).
    ///
    /// The report was a profile menu a hover had opened that would not close
    /// once the pointer came to rest in the empty stretch of the title bar. Two
    /// readings of that had to be told apart before it could be fixed, and this
    /// is where both are written down:
    ///
    /// * it is **not** the `⌄` claiming the space. [`hit_tab_chrome`] answers
    ///   `None` for every pixel of the band, so nothing in the strip ever
    ///   reports [`ChromeTarget::NewTabMenu`] for a point out there;
    /// * it is that the band is **Win32's**. [`title_bar_app_run_right_px`] ends
    ///   the app's run at the `⌄`'s right edge and
    ///   `bt_platform::custom_frame_hit_test` turns everything from there to the
    ///   caption run into `HTCAPTION` — a region winit reports no `CursorMoved`
    ///   for at all, because its Windows backend handles `WM_MOUSEMOVE` and
    ///   `WM_MOUSELEAVE` and not `WM_NCMOUSEMOVE`.
    ///
    /// So a hand resting in the band produces exactly one `CursorLeft` and then
    /// silence, and "the pointer is away" can only reach the `⌄` clocks through
    /// the leave door — which is what `Runtime::pointer_left` now says.
    ///
    /// Red gate: widen `new_tab_menu` to the caption run and the first
    /// assertion fails; hand `title_bar_app_run_right_px` the window's width
    /// and the second does.
    #[test]
    fn the_title_bar_band_right_of_the_chevron_is_win32s_and_not_the_chevrons() {
        use bt_platform::{CustomFrameHit, CustomFrameMetrics, custom_frame_hit_test};
        let (width, scale, tabs) = (1920.0_f32, 1.0_f32, 1_usize);
        let rail = RailState::default();
        let trailers = resting(tabs);
        let chevron = tab_strip_geometry(width, scale, &trailers, 0, 0.0).new_tab_menu;
        let run_right = title_bar_app_run_right_px(width, scale, tabs, rail);
        assert_eq!(
            run_right,
            chevron[2].ceil() as i32,
            "the app's run in the bar ends at the `⌄`, which is the whole of \
             what the WM_NCHITTEST bridge is told"
        );
        let frame = CustomFrameMetrics {
            width: width as i32,
            height: 1080,
            title_bar_height: 40,
            tab_strip_right_px: run_right,
            caption_button_width: 46,
            caption_button_count: 4,
            resize_border: 8,
            resizable: true,
        };
        let y = ((chevron[1] + chevron[3]) / 2.0).round() as i32;

        // The button itself is the app's, and the gate hears `Button` there.
        let on = ((chevron[0] + chevron[2]) / 2.0).round() as i32;
        assert_eq!(
            hit_tab_chrome(width, scale, &trailers, 0, 0.0, f64::from(on), f64::from(y)),
            Some(ChromeTarget::NewTabMenu),
            "the `⌄` answers at its own centre"
        );
        assert_eq!(
            custom_frame_hit_test(frame, on, y),
            CustomFrameHit::Client,
            "and Win32 hands the button's pixels to the client, so it gets moves"
        );

        // And the band the report is about — the whole of it, every 17th pixel.
        let buttons_left = frame.width - frame.caption_button_width * frame.caption_button_count;
        assert!(buttons_left > run_right, "there is a band to test");
        for x in (run_right..buttons_left).step_by(17) {
            assert_eq!(
                hit_tab_chrome(width, scale, &trailers, 0, 0.0, f64::from(x), f64::from(y)),
                None,
                "x={x} lies outside the `⌄`'s box, so nothing in the strip claims it"
            );
            assert_eq!(
                custom_frame_hit_test(frame, x, y),
                CustomFrameHit::Caption,
                "x={x} is the window's own drag handle, and no pointer move is \
                 ever reported from it"
            );
        }
    }

    /// The box the tooltip anchors its `NN%` on is the box the strip draws the
    /// mark in — read off the sprite the strip actually emitted, not recomputed.
    #[test]
    fn the_mark_box_the_tooltip_anchors_on_is_the_box_the_strip_draws_in() {
        for scale in [1.0_f32, 1.5, 2.0] {
            let dpi_milli = (scale * 1_000.0) as u32;
            let metrics = seat_metrics(dpi_milli);
            let seats = Seats::lone_terminal();
            let layout = solved(
                &seats,
                viewport_of((960.0 * scale) as u32, (600.0 * scale) as u32, dpi_milli),
                &metrics,
            );
            let tabs = plain_tabs(3);
            let (_, _, sprites) = build_chrome_for_tabs(
                &seats,
                &layout,
                scale,
                ChromePointer {
                    hover: None,
                    dragging: None,
                    ..ChromePointer::default()
                },
                ChromeContent {
                    head_ink: HeadInk::default(),
                    active_ink: TabInk::default(),
                    tabs: &tabs,
                    active_tab: 0,
                    grabbed: None,
                    strip_preview: None,
                    float_shown: &[],
                    tab_scroll: 0.0,
                    rail: RailState::default(),
                    rail_scroll: 0.0,
                    // The settled column: every geometry in this module is measured at
                    // the end of the entrance, which is where it spends its whole life.
                    focus_reveal: 1.0,
                    focus_thumbnails: &[],
                    preview_titles: &[],
                    terminal_names: &NO_TERMINAL_NAMES,
                    leaf_marks: &NO_LEAF_MARKS,
                    files_names: &NO_FILES_NAMES,
                    files_name_widths: &NO_FILES_NAME_WIDTHS,
                    files_root_open: None,
                    files_trees: &NO_FILES_TREES,
                    files_views: &NO_FILES_VIEWS,
                    git_pages: &NO_GIT_PAGES,
                    git_graphs: &NO_GIT_GRAPHS,
                    preview_messages: &[],
                    preview_feet: &[],
                    preview_heads: &[],
                    preview_rails: &[],
                    preview_cards: &[],
                    fit_overflow: None,
                    profile_menu_open: false,
                    chevron_turn: 0.0,
                    pane_motion: PaneMotionFrame::default(),
                    search_seat: None,
                    pane_menu_seat: None,
                    resizing_cards: None,
                },
            )
            .flattened();
            let geometry = tab_strip_geometry(960.0 * scale, scale, &resting(3), 0, 0.0);
            // Compared as sets, because the strip paints the quiet tabs first
            // and the active one last (`.tab.active { z-index: 1 }`), so draw
            // order is deliberately not strip order.
            let mut anchored: Vec<[f32; 4]> = geometry
                .tabs
                .iter()
                .map(|tab| tab_mark_box(tab, scale))
                .collect();
            let mut drawn: Vec<[f32; 4]> = sprites
                .iter()
                .filter(|sprite| matches!(sprite.mark, ChromeMark::ProfilePowerShell))
                .map(|sprite| sprite.rect)
                .collect();
            let by_left =
                |a: &[f32; 4], b: &[f32; 4]| a[0].partial_cmp(&b[0]).expect("finite lefts");
            anchored.sort_by(by_left);
            drawn.sort_by(by_left);
            assert_eq!(anchored, drawn, "at {scale}x");
            // And each is square and inside the tab it belongs to.
            for (tab, mark) in geometry.tabs.iter().zip(&anchored) {
                assert!((mark[2] - mark[0] - (mark[3] - mark[1])).abs() < 1e-4);
                assert!(mark[0] >= tab.body[0]);
                assert!(mark[2] <= tab.body[2]);
            }
        }
    }

    #[test]
    fn multi_tab_strip_is_equal_width_and_exposes_plus_close_and_middle_click_targets() {
        for scale in [1.0, 1.25, 1.5, 2.0] {
            let geometry = tab_strip_geometry(960.0 * scale, scale, &resting(4), 2, 0.0);
            assert_eq!(geometry.tabs.len(), 4);
            let widths = geometry
                .tabs
                .iter()
                .map(|tab| tab.body[2] - tab.body[0])
                .collect::<Vec<_>>();
            assert!(
                widths
                    .windows(2)
                    .all(|pair| (pair[0] - pair[1]).abs() < 0.01)
            );
            assert!(widths[0] <= WINDOW_TAB_MAX_WIDTH_LOGICAL_PX * scale);

            let plus = geometry.new_tab;
            assert_eq!(
                hit_tab_chrome(
                    960.0 * scale,
                    scale,
                    &resting(4),
                    2,
                    0.0,
                    f64::from((plus[0] + plus[2]) / 2.0),
                    f64::from((plus[1] + plus[3]) / 2.0),
                ),
                Some(ChromeTarget::NewTab)
            );
            let close = geometry.tabs[2].close.expect("the active tab keeps its ×");
            assert_eq!(
                hit_tab_chrome(
                    960.0 * scale,
                    scale,
                    &resting(4),
                    2,
                    0.0,
                    f64::from((close[0] + close[2]) / 2.0),
                    f64::from((close[1] + close[3]) / 2.0),
                ),
                Some(ChromeTarget::TabClose(2))
            );
            let body = geometry.tabs[1].body;
            assert_eq!(
                hit_tab_chrome(
                    960.0 * scale,
                    scale,
                    &resting(4),
                    2,
                    0.0,
                    f64::from(body[0] + 2.0 * scale),
                    f64::from((body[1] + body[3]) / 2.0),
                ),
                Some(ChromeTarget::Tab(1)),
                "the tab body is the target consumed by middle-click close"
            );
        }
    }

    #[test]
    fn tab_count_layout_changes_publish_a_new_strip_right_edge() {
        for scale in [1.0, 1.25, 1.5, 2.0] {
            let width = 960.0 * scale;
            let one = tab_strip_right_px(width, scale, 1);
            let two = tab_strip_right_px(width, scale, 2);
            assert!(
                two > one,
                "adding a tab must move the edge at scale {scale}"
            );
            assert_eq!(
                one,
                tab_strip_geometry(width, scale, &resting(1), 0, 0.0).new_tab_menu[2].ceil() as i32,
                "the published edge includes both end buttons at scale {scale}"
            );
        }
    }

    /// The strip at one scale, with `hover` wherever the caller says.
    fn strip_chrome(
        scale: f32,
        titles: &[String],
        active_tab: usize,
        hover: Option<ChromeTarget>,
        profile_menu_open: bool,
    ) -> (Vec<ChromeQuad>, Vec<ChromeLabel>, Vec<ChromeSprite>) {
        let tabs = titles
            .iter()
            .map(|title| TabContent {
                flight: 0.0,
                mark_kind: ChromeMark::ProfilePowerShell,
                title: title.clone(),
                pane_count: 1,
                badge_text_width: 0.0,
                mark: TabMarkState::default(),
                trailer: TabTrailer::default(),
                offset: 0.0,
                landing: 0.0,
                edit: None,
            })
            .collect::<Vec<_>>();
        strip_chrome_of(scale, &tabs, active_tab, 0.0, hover, profile_menu_open)
    }

    /// The strip at one scale, told exactly what each tab holds and how far it
    /// is scrolled, with the chevron settled wherever its menu is.
    ///
    /// Settled is the right default for every caller but the turn's own tests:
    /// 140ms after the click the arrow has arrived, and a test that is not
    /// about the transition is asking about a strip at rest.
    fn strip_chrome_of(
        scale: f32,
        tabs: &[TabContent],
        active_tab: usize,
        tab_scroll: f32,
        hover: Option<ChromeTarget>,
        profile_menu_open: bool,
    ) -> (Vec<ChromeQuad>, Vec<ChromeLabel>, Vec<ChromeSprite>) {
        strip_chrome_of_turn(
            scale,
            tabs,
            active_tab,
            tab_scroll,
            hover,
            profile_menu_open,
            f32::from(u8::from(profile_menu_open)),
        )
    }

    /// The same, with the arrow caught partway through its turn.
    fn strip_chrome_of_turn(
        scale: f32,
        tabs: &[TabContent],
        active_tab: usize,
        tab_scroll: f32,
        hover: Option<ChromeTarget>,
        profile_menu_open: bool,
        chevron_turn: f32,
    ) -> (Vec<ChromeQuad>, Vec<ChromeLabel>, Vec<ChromeSprite>) {
        // A 960x600 *logical* window, so the strip's own geometry can be
        // restated at the same width the builder will see.
        let dpi_milli = (scale * 1_000.0) as u32;
        let metrics = seat_metrics(dpi_milli);
        let seats = Seats::lone_terminal();
        let layout = solved(
            &seats,
            viewport_of((960.0 * scale) as u32, (600.0 * scale) as u32, dpi_milli),
            &metrics,
        );
        build_chrome_for_tabs(
            &seats,
            &layout,
            scale,
            ChromePointer {
                hover,
                ..ChromePointer::default()
            },
            ChromeContent {
                head_ink: HeadInk::default(),
                active_ink: TabInk::default(),
                tabs,
                active_tab,
                grabbed: None,
                strip_preview: None,
                float_shown: &[],
                tab_scroll,
                rail: RailState::default(),
                rail_scroll: 0.0,
                // The settled column: every geometry in this module is measured at
                // the end of the entrance, which is where it spends its whole life.
                focus_reveal: 1.0,
                focus_thumbnails: &[],
                preview_titles: &[],
                terminal_names: &NO_TERMINAL_NAMES,
                leaf_marks: &NO_LEAF_MARKS,
                files_names: &NO_FILES_NAMES,
                files_name_widths: &NO_FILES_NAME_WIDTHS,
                files_root_open: None,
                files_trees: &NO_FILES_TREES,
                files_views: &NO_FILES_VIEWS,
                git_pages: &NO_GIT_PAGES,
                git_graphs: &NO_GIT_GRAPHS,
                preview_messages: &[],
                preview_feet: &[],
                preview_heads: &[],
                preview_rails: &[],
                preview_cards: &[],
                fit_overflow: None,
                profile_menu_open,
                chevron_turn,
                pane_motion: PaneMotionFrame::default(),
                search_seat: None,
                pane_menu_seat: None,
                resizing_cards: None,
            },
        )
        .flattened()
    }

    fn strip_titles(count: usize) -> Vec<String> {
        (0..count).map(|index| format!("tab {index}")).collect()
    }

    // ── C28-C43: the file tree's rows ──────────────────────────────────────

    fn tree_row(
        key: &str,
        name: &str,
        depth: usize,
        kind: crate::files::RowKind,
    ) -> crate::files::TreeRow {
        crate::files::TreeRow {
            key: key.to_owned(),
            name: name.to_owned(),
            depth,
            kind,
        }
    }

    /// The three channels a tree draws into, named so the tests below read as
    /// questions about the picture rather than about tuple positions.
    struct TreeChrome {
        quads: Vec<ChromeQuad>,
        labels: Vec<ChromeLabel>,
        sprites: Vec<ChromeSprite>,
    }

    /// A column beside a terminal, showing `rows`, with the chrome it produces.
    fn files_chrome(
        content: FilesTreeContent,
        hover_row: Option<usize>,
    ) -> (Seats, SeatLayout, SeatId, TreeChrome) {
        let seats = term_beside_files();
        let column = seats.files().first().copied().expect("a files column");
        // Built here rather than by the caller because the seat id is minted by
        // the tree: a hover aimed at a guessed id is a hover at nothing, and it
        // fails by drawing the resting picture rather than by saying so.
        let hover = hover_row.map(|index| ChromeTarget::FilesRow {
            seat: column,
            index,
        });
        files_chrome_hovering(content, hover)
    }

    /// The same, with the pointer put on whatever part of the column the caller
    /// names — the foot as readily as a row.
    fn files_chrome_hovering(
        content: FilesTreeContent,
        hover: Option<ChromeTarget>,
    ) -> (Seats, SeatLayout, SeatId, TreeChrome) {
        let seats = term_beside_files();
        let metrics = seat_metrics(1_000);
        let layout = solved(&seats, viewport_of(960, 600, 1_000), &metrics);
        let column = seats.files().first().copied().expect("a files column");
        let mut trees = BTreeMap::new();
        trees.insert(column, content);
        let (quads, labels, sprites) = build_chrome_for_tabs(
            &seats,
            &layout,
            1.0,
            ChromePointer {
                hover,
                ..ChromePointer::default()
            },
            ChromeContent {
                head_ink: HeadInk::default(),
                active_ink: TabInk::default(),
                tabs: &[],
                files_views: &NO_FILES_VIEWS,
                git_pages: &NO_GIT_PAGES,
                git_graphs: &NO_GIT_GRAPHS,
                active_tab: 0,
                grabbed: None,
                strip_preview: None,
                float_shown: &[],
                tab_scroll: 0.0,
                rail: RailState::default(),
                rail_scroll: 0.0,
                // The settled column: every geometry in this module is measured at
                // the end of the entrance, which is where it spends its whole life.
                focus_reveal: 1.0,
                focus_thumbnails: &[],
                preview_titles: &[],
                terminal_names: &NO_TERMINAL_NAMES,
                leaf_marks: &NO_LEAF_MARKS,
                files_names: &NO_FILES_NAMES,
                files_name_widths: &NO_FILES_NAME_WIDTHS,
                files_root_open: None,
                files_trees: &trees,
                preview_messages: &[],
                preview_feet: &[],
                preview_heads: &[],
                preview_rails: &[],
                preview_cards: &[],
                fit_overflow: None,
                profile_menu_open: false,
                chevron_turn: 0.0,
                pane_motion: PaneMotionFrame::default(),
                search_seat: None,
                pane_menu_seat: None,
                resizing_cards: None,
            },
        )
        .flattened();
        (
            seats,
            layout,
            column,
            TreeChrome {
                quads,
                labels,
                sprites,
            },
        )
    }

    fn three_row_tree() -> FilesTreeContent {
        FilesTreeContent {
            foot_dissolved: 0.0,
            rows: vec![
                tree_row(
                    "/src",
                    "src",
                    0,
                    crate::files::RowKind::Directory { open: true },
                ),
                tree_row("/src/main.rs", "main.rs", 1, crate::files::RowKind::File),
                tree_row("/a.txt", "a.txt", 0, crate::files::RowKind::File),
            ],
            badges: crate::git_panel::GitTreeBadges::default(),
            scroll_px: 0.0,
            selected: None,
            turns: BTreeMap::new(),
            focus_ring: false,
            foot_path: String::new(),
            foot_revealed: false,
        }
    }

    /// PIN — C31. The indent is `6 + depth * 14`, counted from the row's own box.
    ///
    /// The two paddings this formula spans are separate declarations
    /// (`.files-tree`'s `4` and `.frow`'s `6`), and the way to get this wrong is
    /// to fold them into one number — which shows up as every row of the tree
    /// standing four pixels too far in and the depth step still looking right.
    #[test]
    fn a_row_is_indented_six_plus_fourteen_per_level_from_its_own_left_edge() {
        let (_, _, _, chrome) = files_chrome(three_row_tree(), None);
        let named = |text: &str| {
            chrome
                .labels
                .iter()
                .find(|label| label.text == text)
                .unwrap_or_else(|| panic!("{text} is drawn"))
                .clone()
        };
        let shallow = named("src");
        let deep = named("main.rs");
        assert_eq!(
            deep.rect[0] - shallow.rect[0],
            FILES_ROW_INDENT_LOGICAL_PX,
            "one level of depth is one indent step and nothing else"
        );
        let sibling = named("a.txt");
        assert_eq!(
            sibling.rect[0], shallow.rect[0],
            "two rows at the same depth start in the same column"
        );
    }

    // ── R32: the letters a tree wears when a Git page is open beside it ─────

    const BADGE_REPO: &str = r"D:\repo";

    /// What one column's open Git page would lend this tree, built through the
    /// door every real answer comes through.
    fn badges_from(porcelain: &[u8]) -> crate::git_panel::GitTreeBadges {
        let root = std::path::PathBuf::from(BADGE_REPO);
        let mut cache = crate::git::GitCache::default();
        cache.retarget(&root);
        assert!(cache.accept(crate::git::GitAnswer::Repo {
            dir: root.clone(),
            outcome: Ok(root.clone()),
        }));
        assert!(cache.accept(crate::git::GitAnswer::Status {
            root: root.clone(),
            outcome: Ok(crate::git::parse_status(porcelain)),
        }));
        crate::git_panel::GitTreeBadges::of(&[(FilesView::Git, &cache)], &root)
    }

    fn label_named<'a>(chrome: &'a TreeChrome, text: &str) -> &'a ChromeLabel {
        chrome
            .labels
            .iter()
            .find(|label| label.text == text)
            .unwrap_or_else(|| panic!("{text} is drawn"))
    }

    /// **P3-6's inline badge, and R32's gate on it.** A file git has something to
    /// say about wears its letter in the row's own right-hand whitespace, and the
    /// name gives up exactly that much width — the badge is never drawn *over* a
    /// name.
    ///
    /// MUTATION: leave `name_right` at `rect[2] - row_pad` when a badge is drawn.
    /// The last assertion fails: the name keeps the full row and the letter
    /// stands on top of whatever is at the end of it.
    #[test]
    fn a_changed_file_wears_its_letter_in_the_rows_own_right_margin() {
        let bare = files_chrome(three_row_tree(), None).3;
        let bare_name = label_named(&bare, "main.rs").rect[2];

        let content = FilesTreeContent {
            badges: badges_from(b"## main\0 M src/main.rs\0"),
            ..three_row_tree()
        };
        let (_, layout, column, chrome) = files_chrome(content, None);
        let body = files_pane_geometry(
            files_pane_rect(&layout, column).expect("the column has a rectangle"),
            1.0,
            false,
        )
        .body;

        // The row `main.rs` is, taken from the geometry the painter used.
        let row = files_tree_geometry(body, 3, 0.0, 1.0).row_rect(1);
        let letter = label_named(&chrome, "M");
        assert!(
            (letter.rect[2] - (row[2] - FILES_ROW_PADDING_X_LOGICAL_PX)).abs() < 0.5,
            "the letter ends at the row's own right inset, at {} against {}",
            letter.rect[2],
            row[2] - FILES_ROW_PADDING_X_LOGICAL_PX
        );
        assert!(
            label_named(&chrome, "main.rs").rect[2] < bare_name,
            "and the name gave up the width it took"
        );
    }

    /// **R32 the other way round: with no Git page open, a tree is exactly the
    /// tree it was.** The default badges are what every caller hands in when no
    /// column of the tab is standing on its page, and this is the whole of "the
    /// badge fades when the panel closes".
    ///
    /// MUTATION: make `GitTreeBadges::of` ignore which page a column is on. The
    /// column in `files_chrome` is on its tree, so this test still passes — but
    /// its twin in `git_panel` fails at once, which is why both exist.
    #[test]
    fn a_tree_with_no_open_page_beside_it_draws_no_letters_at_all() {
        let (_, _, _, chrome) = files_chrome(three_row_tree(), None);
        assert!(
            !chrome
                .labels
                .iter()
                .any(|label| label.text.chars().count() == 1
                    && "MADRCUT?".contains(label.text.as_str())),
            "no status letter anywhere in the picture"
        );
    }

    /// A folder says one thing and one thing only: something under here is
    /// changed. It is a dot because git makes no claim about directories.
    #[test]
    fn a_folder_over_a_change_wears_one_dot_and_no_letter() {
        let content = FilesTreeContent {
            badges: badges_from(b"## main\0 M src/main.rs\0"),
            ..three_row_tree()
        };
        let (_, _, _, chrome) = files_chrome(content, None);
        let dots: Vec<&ChromeSprite> = chrome
            .sprites
            .iter()
            .filter(|sprite| {
                matches!(sprite.mark, ChromeMark::ControlPill { .. })
                    && (sprite.rect[2]
                        - sprite.rect[0]
                        - crate::git_panel::FILES_BADGE_DOT_LOGICAL_PX)
                        .abs()
                        < 0.5
            })
            .collect();
        assert_eq!(dots.len(), 1, "one folder is over the change, and only one");
        let src = label_named(&chrome, "src");
        assert!(
            dots[0].rect[0] > src.rect[2],
            "and it stands past the end of the folder's own name column"
        );
    }

    /// PIN — C33/C34. A directory row wears a triangle and a folder; a file row
    /// keeps the triangle's slot empty and wears the file mark.
    ///
    /// `visibility: hidden` and not `display: none` is the whole of this: a file
    /// with no triangle *slot* would put its name where a folder's icon is, and
    /// the column would look like two lists interleaved.
    #[test]
    fn a_file_row_holds_the_triangles_place_without_drawing_one() {
        let (_, _, _, chrome) = files_chrome(three_row_tree(), None);
        let triangles = chrome
            .sprites
            .iter()
            .filter(|sprite| matches!(sprite.mark, ChromeMark::TreeDisclosure { .. }))
            .count();
        assert_eq!(triangles, 1, "only the one directory row has a triangle");
        let folders = chrome
            .sprites
            .iter()
            .filter(|sprite| sprite.mark == ChromeMark::FolderOpen)
            .count();
        assert_eq!(folders, 1, "and it is open, so it wears the open folder");
        let files = chrome
            .sprites
            .iter()
            .filter(|sprite| sprite.mark == ChromeMark::File)
            .count();
        assert_eq!(files, 2, "both file rows wear the file mark");
        // The slot is held: a file's name starts where a folder's name starts.
        let folder_name = chrome
            .labels
            .iter()
            .find(|label| label.text == "src")
            .expect("the folder row is drawn");
        let file_name = chrome
            .labels
            .iter()
            .find(|label| label.text == "a.txt")
            .expect("the file row is drawn");
        assert_eq!(folder_name.rect[0], file_name.rect[0]);
    }

    /// PIN — C33. The triangle is turned, not swapped: a shut row and an open
    /// row ask for the same glyph at two angles.
    #[test]
    fn the_disclosure_triangle_turns_between_shut_and_open() {
        let shut = FilesTreeContent {
            rows: vec![tree_row(
                "/src",
                "src",
                0,
                crate::files::RowKind::Directory { open: false },
            )],
            ..FilesTreeContent::default()
        };
        let open = FilesTreeContent {
            rows: vec![tree_row(
                "/src",
                "src",
                0,
                crate::files::RowKind::Directory { open: true },
            )],
            ..FilesTreeContent::default()
        };
        let angle = |content: FilesTreeContent| {
            let (_, _, _, chrome) = files_chrome(content, None);
            chrome
                .sprites
                .iter()
                .find_map(|sprite| match sprite.mark {
                    ChromeMark::TreeDisclosure { turned_degrees } => Some(turned_degrees),
                    _ => None,
                })
                .expect("a directory row has a triangle")
        };
        assert_eq!(angle(shut), 0);
        assert_eq!(angle(open), crate::marks::TREE_DISCLOSURE_OPEN_DEGREES);
    }

    /// PIN — C32. Selection is a fact about the tree and outranks the pointer.
    ///
    /// `.frow.sel` and `.frow:hover` carry equal specificity and the selected
    /// rule is written second, so a selected row under the pointer keeps the
    /// selected fill. Reading it the other way makes the selection flicker away
    /// exactly when you reach for it.
    #[test]
    fn a_selected_row_under_the_pointer_stays_selected() {
        let mut content = three_row_tree();
        content.selected = Some("/src".to_owned());
        let (_, _, _, chrome) = files_chrome(content, Some(0));
        let palette = chrome_palette();
        let fills: Vec<[u8; 3]> = chrome
            .sprites
            .iter()
            .filter(|sprite| matches!(sprite.mark, ChromeMark::ControlPill { .. }))
            .map(|sprite| sprite.color)
            .collect();
        assert!(
            fills.contains(&palette.files_row_selected),
            "the selected row wears the selected fill, not the hover one: {fills:?}"
        );
        assert!(
            !fills.contains(&palette.files_row_hover),
            "and nothing wears the hover fill, because the one hovered row is \
             the selected one: {fills:?}"
        );
    }

    /// PIN — B15. The root button hugs its name, and is pressed where it is
    /// drawn.
    ///
    /// The mock-up's own comment is the assertion: `flex: 0 1 auto` and not
    /// `flex: 1`, because a button that took the head's whole slack would light
    /// a bar the width of the column on hover and "read as a long dark smear".
    /// A short name has to leave most of the head alone.
    #[test]
    fn the_root_button_is_the_width_of_the_name_and_not_the_width_of_the_head() {
        let seats = term_beside_files();
        let metrics = seat_metrics(1_000);
        let layout = solved(&seats, viewport_of(960, 600, 1_000), &metrics);
        let column = seats.files().first().copied().expect("a files column");
        let placement = layout
            .rects
            .iter()
            .find(|placement| placement.id == column)
            .expect("the column is placed");
        let device = placement.device_rect.expect("the column has a rectangle");
        let rect = [
            device.left as f32,
            device.top as f32,
            device.right as f32,
            device.bottom as f32,
        ];
        let head = pane_head_geometry(rect, SeatKind::Files, 1.0);

        let short = files_root_box(&head, 1.0, 30.0).expect("a named head has a button");
        assert!(
            short[2] < head.title[2] - 40.0,
            "a 30px name must leave the rest of the head alone: {short:?} in {:?}",
            head.title
        );
        assert!(
            short[0] < head.title[0],
            "the fill reaches past its letters"
        );
        assert!(
            short[1] >= head.head[1] && short[3] <= head.head[3],
            "and stays inside the head it sits in"
        );

        // A name longer than the head has stops at the head's own edge rather
        // than growing under the `×`.
        let long = files_root_box(&head, 1.0, 10_000.0).expect("a long name still has a button");
        assert!(long[2] <= head.title[2]);

        // The hit test reads the same box from the same measurement.
        let mut widths = BTreeMap::new();
        widths.insert(column, 30.0);
        let middle = |rect: [f32; 4]| ((rect[0] + rect[2]) / 2.0, (rect[1] + rect[3]) / 2.0);
        let (x, y) = middle(short);
        assert_eq!(
            hit_files_root(&layout, &widths, 1.0, f64::from(x), f64::from(y)),
            Some(ChromeTarget::FilesRoot(column))
        );
        // Just past its right edge is the head again — the drag handle, not the
        // button.
        assert_eq!(
            hit_files_root(
                &layout,
                &widths,
                1.0,
                f64::from(short[2] + 4.0),
                f64::from(y)
            ),
            None
        );
        // A head nobody has measured offers no button at all, rather than one of
        // some invented width.
        assert_eq!(
            hit_files_root(
                &layout,
                &NO_FILES_NAME_WIDTHS,
                1.0,
                f64::from(x),
                f64::from(y)
            ),
            None
        );
    }

    /// PIN — B17. The button wins over the drag handle it lives inside, and the
    /// `×` still wins over the button.
    #[test]
    fn the_root_button_answers_before_the_handle_and_never_over_the_close() {
        let seats = term_beside_files();
        let metrics = seat_metrics(1_000);
        let layout = solved(&seats, viewport_of(960, 600, 1_000), &metrics);
        let column = seats.files().first().copied().expect("a files column");
        let placement = layout
            .rects
            .iter()
            .find(|placement| placement.id == column)
            .expect("the column is placed");
        let device = placement.device_rect.expect("the column has a rectangle");
        let rect = [
            device.left as f32,
            device.top as f32,
            device.right as f32,
            device.bottom as f32,
        ];
        let head = pane_head_geometry(rect, SeatKind::Files, 1.0);
        let close = head.close.expect("the head is wide enough for its ×");

        // A name wide enough to want the whole head is still clamped clear of
        // the close button, so the two boxes can never overlap.
        let mut widths = BTreeMap::new();
        widths.insert(column, 10_000.0);
        let button = files_root_box(&head, 1.0, 10_000.0).expect("a button");
        assert!(
            button[2] <= close[0],
            "the button stops before the ×: {button:?} vs {close:?}"
        );
        let (cx, cy) = ((close[0] + close[2]) / 2.0, (close[1] + close[3]) / 2.0);
        assert_eq!(
            hit_files_root(&layout, &widths, 1.0, f64::from(cx), f64::from(cy)),
            None,
            "the × is not the root button however long the name is"
        );
        assert_eq!(
            hit_chrome(
                &seats,
                &layout,
                1.0,
                Some(column),
                f64::from(cx),
                f64::from(cy)
            ),
            Some(ChromeTarget::PaneClose(column))
        );
    }

    /// PIN — C32's third half: the ring is drawn on the selection, in the
    /// accent, and only when the column says it has earned one.
    ///
    /// The fill says *where you are standing in this tree*; the accent ring says
    /// *this tree is the one an arrow key belongs to*. Two panes can show a
    /// selection at once and only one of them can have the keyboard, so a build
    /// that drew the fill alone would leave the user pressing ↓ with no way to
    /// know which list was about to move — and one that hid the fill without
    /// focus would lose the standing place every time you clicked into a shell.
    ///
    /// **This half is only the drawing.** Whether the flag is set is
    /// `:focus-visible` and belongs to the host — see
    /// `a_pointer_takes_the_keyboard_without_a_ring_and_the_first_key_lights_it`
    /// in `main.rs`, which is the half the 2026-08-12 ruling was about.
    #[test]
    fn only_a_column_that_has_earned_the_ring_draws_one_on_its_selection() {
        let ring_of = |focus_ring: bool| {
            let mut content = three_row_tree();
            content.selected = Some("/a.txt".to_owned());
            content.focus_ring = focus_ring;
            let (_, _, _, chrome) = files_chrome(content, None);
            chrome.sprites.iter().find_map(|sprite| match sprite.mark {
                ChromeMark::ControlPillRing { stroke_px, .. } => {
                    Some((stroke_px, sprite.color, sprite.rect))
                }
                _ => None,
            })
        };
        assert_eq!(
            ring_of(false),
            None,
            "a column that has not earned a ring shows its selection and claims nothing"
        );
        let (stroke_px, color, rect) = ring_of(true).expect("a column that has earned one rings");
        assert_eq!(color, chrome_palette().accent);
        assert!(stroke_px >= 1, "a ring of no thickness is not drawn");

        // The fill is there either way: `.frow.sel { background: var(--active) }`
        // carries no `:focus-visible`, so the standing place survives the ring
        // going out — which is the half of C32 the ruling did *not* touch.
        for focus_ring in [false, true] {
            let mut content = three_row_tree();
            content.selected = Some("/a.txt".to_owned());
            content.focus_ring = focus_ring;
            let (_, _, _, chrome) = files_chrome(content, None);
            assert!(
                chrome
                    .sprites
                    .iter()
                    .any(|sprite| sprite.color == chrome_palette().files_row_selected),
                "ring {focus_ring}: the selected fill is a fact about the tree"
            );
        }

        // The ring is the selected row's own box, so it lands on the selection
        // and not merely somewhere in the list.
        let mut content = three_row_tree();
        content.selected = Some("/a.txt".to_owned());
        content.focus_ring = true;
        let (_, layout, column, _) = files_chrome(content, None);
        let body = files_body_rect(&layout, column, 1.0, false).expect("the column has a body");
        let geometry = files_tree_geometry(body, 3, 0.0, 1.0);
        assert_eq!(rect, geometry.row_rect(2), "the third row is `/a.txt`");
    }

    // ── the preview seat's text body and its "no preview" card ──────────────

    /// PIN — R2 乙案, on the preview body, **on both axes**.
    ///
    /// The clamp reads its ceiling off [`preview_mono_geometry`], so a body that
    /// holds its whole document cannot be scrolled at all and one that does not
    /// stops exactly where the content does. The horizontal axis is the one this
    /// slice added and the one that is easy to leave unbounded: a line that runs
    /// off the edge invites a scroller that never ends.
    ///
    /// Mutation: drop either `.max(0.0)` from `max_scroll`, which lets a body
    /// scroll off its own top or its own left edge.
    #[test]
    fn a_preview_body_scrolls_exactly_as_far_as_it_has_content_on_both_axes() {
        let body = [0.0, 100.0, 400.0, 300.0];
        let metrics = preview_text_metrics(1.0);
        // 12.5 × 1.5 = 18.75, rounded to 19; padding 10 and 12.
        assert_eq!(metrics.line_height, 19.0);
        let short = preview_mono_geometry(body, metrics, 19.0 * 4.0, 10, 8.0, [0.0, 0.0]);
        assert_eq!(short.content_height, 20.0 + 19.0 * 4.0);
        assert_eq!(short.content_width, 24.0 + 80.0);
        assert_eq!(
            short.max_scroll,
            [0.0, 0.0],
            "four short lines fit in four hundred by two hundred"
        );

        let long = preview_mono_geometry(body, metrics, 19.0 * 100.0, 120, 8.0, [0.0, 0.0]);
        assert_eq!(long.max_scroll[1], 20.0 + 19.0 * 100.0 - 200.0);
        assert_eq!(long.max_scroll[0], 24.0 + 960.0 - 400.0);
        // What is clamped *against* is pinned here; the clamp itself belongs to
        // the runtime, which asks each of the four bodies for its own extent.

        let scrolled = preview_mono_geometry(body, metrics, 19.0 * 100.0, 120, 8.0, [40.0, 38.0]);
        assert_eq!(
            scrolled.line_rect(2)[1],
            110.0,
            "two lines of scroll puts the third line where the first one was"
        );
        assert_eq!(
            scrolled.line_rect(2)[0],
            -28.0,
            "and forty pixels of it moves the left edge left by forty"
        );
    }

    /// PIN — P108's named double bug: **a diff's tint spans the whole width.**
    ///
    /// `.pv-diff` is `width: max-content; min-width: 100%` for one reason, and
    /// the mock-up's own comment says it: half-width tints. A band derived from
    /// the text stops where the addition stops, and slides sideways the moment
    /// the body is scrolled horizontally. This one is the viewport's, so it can
    /// do neither.
    ///
    /// Mutation: return `row_rect` from `band_rect`.
    #[test]
    fn a_diffs_tint_spans_the_whole_body_at_every_scroll() {
        let body = [40.0, 100.0, 440.0, 300.0];
        let metrics = preview_diff_metrics(1.0);
        // 12.5 × 1.65 = 20.6, rounded to 21.
        assert_eq!(metrics.line_height, 21.0);
        for scroll in [[0.0, 0.0], [180.0, 42.0], [1000.0, 0.0]] {
            let geometry = preview_mono_geometry(body, metrics, 21.0 * 200.0, 300, 8.0, scroll);
            let band = geometry.band_rect(21.0 * 3.0);
            assert_eq!(
                [band[0], band[2]],
                [body[0], body[2]],
                "the band is the body's width at scroll {scroll:?}"
            );
            let row = geometry.row_rect(21.0 * 3.0);
            assert_eq!(band[1], row[1], "and it sits on its own line");
            assert_eq!(band[3] - band[1], metrics.line_height);
        }
    }

    /// PIN — the grid's cells are where its own column widths say.
    ///
    /// The heading row and the data rows are laid out by one derivation, so a
    /// column cannot be one width in the head and another in the body — which is
    /// the way a hand-built table always breaks.
    ///
    /// Mutation: drop the border from `row_height` or from `content_width`.
    #[test]
    fn a_tables_columns_are_one_width_from_head_to_foot() {
        let body = [0.0, 0.0, 600.0, 400.0];
        let geometry = preview_table_geometry(body, &[6, 4, 8], 3, 8.0, 1.0, [0.0, 0.0]);
        // 1 border + 10 padding on each side + cells × 8.
        assert_eq!(geometry.column_widths, vec![69.0, 53.0, 85.0]);
        assert_eq!(geometry.content_width, 69.0 + 53.0 + 85.0 + 1.0);
        // 1 border + 4 padding each side + round(12 × 1.4).
        assert_eq!(geometry.row_height, 1.0 + 8.0 + 17.0);
        for row in 0..3 {
            let head = geometry.cell_rect(0, 1);
            let cell = geometry.cell_rect(row, 1);
            assert_eq!([cell[0], cell[2]], [head[0], head[2]], "row {row}");
        }
        let text = geometry.cell_text_rect(0, 0);
        let cell = geometry.cell_rect(0, 0);
        assert!(text[0] > cell[0] && text[1] > cell[1] && text[2] < cell[2]);
        assert_eq!(
            geometry.row_rect(0)[2] - geometry.row_rect(0)[0],
            geometry.content_width,
            "the heading fill runs the width of the table, not of one cell"
        );
    }

    /// PIN — the card's button is the button you can press.
    ///
    /// `preview_card_geometry` is the single derivation the painter and
    /// [`hit_preview_card_button`] both read, which is the rule
    /// [`FilesTreeGeometry`] states in as many words. Asserted as the *agreement*
    /// rather than as a rectangle, because a rectangle written here would be a
    /// third opinion about the same box.
    ///
    /// Mutation: change the padding constant in either the width or the height
    /// of [`preview_card_geometry`] — the point outside the button then lands
    /// inside it, or the point inside stops answering.
    #[test]
    fn the_cards_button_answers_for_exactly_the_box_it_is_drawn_in() {
        let body = [40.0, 60.0, 440.0, 460.0];
        let geometry = preview_card_geometry(body, 120.0, false, 1.0);
        assert!(
            geometry.icon[3] < geometry.notice[1] && geometry.notice[3] < geometry.button[1],
            "icon over sentence over button, in that order"
        );
        assert_eq!(
            (geometry.button[0] + geometry.button[2]) / 2.0,
            (body[0] + body[2]) / 2.0,
            "and the column is centred on the body"
        );
        // 120 of caption plus 12 of padding and 1 of border on each side.
        assert_eq!(geometry.button[2] - geometry.button[0], 146.0);
        let inside = (
            (geometry.button[0] + geometry.button[2]) / 2.0,
            (geometry.button[1] + geometry.button[3]) / 2.0,
        );
        assert!(contains(geometry.button, inside.0, inside.1));
        assert!(
            !contains(geometry.button, geometry.button[0] - 1.0, inside.1),
            "one pixel to the left of the frame is not the button"
        );
        assert!(
            !contains(geometry.button, inside.0, geometry.notice[1]),
            "and neither is the sentence above it"
        );
    }

    /// PIN — C32, the other half. A selection shows with no pointer anywhere
    /// near it, because it is not a pointer state.
    #[test]
    fn a_selection_shows_with_the_pointer_elsewhere() {
        let mut content = three_row_tree();
        content.selected = Some("/a.txt".to_owned());
        let (_, _, _, chrome) = files_chrome(content, None);
        let palette = chrome_palette();
        assert!(
            chrome
                .sprites
                .iter()
                .any(|sprite| sprite.color == palette.files_row_selected),
            "the selected row is filled with no hover in the window at all"
        );
    }

    /// PIN — the hover fill is reachable at all, so the test above is not
    /// vacuous: an unselected row under the pointer wears it.
    #[test]
    fn an_unselected_row_under_the_pointer_wears_the_hover_fill() {
        let (_, _, _, chrome) = files_chrome(three_row_tree(), Some(2));
        let palette = chrome_palette();
        assert!(
            chrome
                .sprites
                .iter()
                .any(|sprite| sprite.color == palette.files_row_hover)
        );
    }

    // ── `.files-pane .files-foot` (mock-up 527-538) ────────────────────────

    /// A three-row column with a path in its foot.
    fn footed_tree(path: &str) -> FilesTreeContent {
        FilesTreeContent {
            foot_dissolved: 0.0,
            foot_path: path.to_owned(),
            ..three_row_tree()
        }
    }

    /// PIN — the foot is the mock-up's, declaration for declaration.
    ///
    /// Every number here is one the mock-up writes at 529-536, and they are
    /// asserted separately because any one of them can be right while the others
    /// are not: a 28px strip with 10px padding is still wrong, and it is wrong in
    /// a way only a ruler catches.
    #[test]
    fn the_foot_is_twenty_eight_pixels_of_hairline_padding_mark_and_path() {
        let rect = [0.0, 0.0, 260.0, 600.0];
        for scale in [1.0_f32, 1.5, 2.0] {
            let rect = [rect[0], rect[1], rect[2] * scale, rect[3] * scale];
            let geometry = files_pane_geometry(rect, scale, false);
            assert_eq!(
                geometry.foot[3] - geometry.foot[1],
                (FILES_FOOT_BAR_LOGICAL_PX * scale).round(),
                "{scale}: `height: 28px`, border included"
            );
            assert_eq!(
                geometry.foot[3], rect[3],
                "{scale}: and it sits on the pane's own floor"
            );
            assert_eq!(
                geometry.foot_edge[1], geometry.foot[1],
                "{scale}: `border-top` is the strip's first row"
            );
            assert_eq!(
                geometry.foot_edge[3] - geometry.foot_edge[1],
                (FILES_FOOT_EDGE_LOGICAL_PX * scale).max(1.0),
                "{scale}: one hairline, never less than a device pixel"
            );
            assert_eq!(
                geometry.foot_mark[0] - geometry.foot[0],
                (FILES_FOOT_PADDING_X_LOGICAL_PX * scale).round(),
                "{scale}: `padding: 0 12px`, the left half"
            );
            assert_eq!(
                geometry.foot[2] - geometry.foot_path[2],
                (FILES_FOOT_PADDING_X_LOGICAL_PX * scale).round(),
                "{scale}: and the right half — the same 12, not the float's 18"
            );
            assert_eq!(
                geometry.foot_mark[2] - geometry.foot_mark[0],
                (FILES_FOOT_MARK_LOGICAL_PX * scale).round(),
                "{scale}: `.foot-ico {{ width: 13px }}`"
            );
            assert_eq!(
                geometry.foot_path[0] - geometry.foot_mark[2],
                FILES_FOOT_GAP_LOGICAL_PX * scale,
                "{scale}: `gap: 6px`"
            );
            // Centred in the flex row, which is the strip below its hairline.
            let above = geometry.foot_mark[1] - geometry.foot_edge[3];
            let below = geometry.foot[3] - geometry.foot_mark[3];
            assert!(
                (above - below).abs() <= 1.0,
                "{scale}: the mark is centred in the strip: {above} above, {below} below"
            );
        }
    }

    /// PIN — **the tree's body stops at the foot, for everyone at once.**
    ///
    /// The connective tissue of the whole change: the painter, the wheel, the hit
    /// test and the keyboard's scroll-into-view all ask one function where the
    /// rows go, so the foot could not be added to three of them and forgotten in
    /// the fourth. Red gate: with the body still running to the pane's floor,
    /// `hit_files_tree` answers with a row for a point inside the strip — a click
    /// on the path selects a file behind it.
    #[test]
    fn the_body_every_reader_gets_stops_at_the_foots_hairline() {
        let content = footed_tree(r"C:\Users\Weiyi");
        let (seats, layout, column, _) = files_chrome(content.clone(), None);
        let rect = files_pane_rect(&layout, column).expect("the column is placed");
        let geometry = files_pane_geometry(rect, 1.0, false);

        assert_eq!(
            files_body_rect(&layout, column, 1.0, false),
            Some(geometry.body),
            "the wheel and the keyboard read the shortened body"
        );
        assert_eq!(
            geometry.body[3], geometry.foot[1],
            "which ends where the strip begins"
        );
        assert_eq!(
            files_body_at(
                &layout,
                1.0,
                false,
                f64::from((rect[0] + rect[2]) / 2.0),
                f64::from(rect[3] - 4.0)
            ),
            None,
            "a wheel notch over the foot is not the list's"
        );

        // And the hit test agrees: the strip answers for itself, and no row is
        // hiding under it.
        let mut trees = BTreeMap::new();
        trees.insert(column, content);
        let inside_foot = (
            f64::from((geometry.foot[0] + geometry.foot[2]) / 2.0),
            f64::from((geometry.foot[1] + geometry.foot[3]) / 2.0),
        );
        assert_eq!(
            hit_files_tree(&layout, &trees, 1.0, false, inside_foot.0, inside_foot.1),
            None,
            "no row lives under the foot"
        );
        assert_eq!(
            hit_files_foot(&seats, &layout, 1.0, inside_foot.0, inside_foot.1),
            Some(ChromeTarget::FilesFoot(column)),
            "and the strip claims its own rectangle"
        );
        assert_eq!(
            hit_files_foot(
                &seats,
                &layout,
                1.0,
                inside_foot.0,
                f64::from(geometry.body[3] - 1.0)
            ),
            None,
            "one pixel above the hairline is still the list"
        );
    }

